insert into public.confessions (id, user_id, content, is_anonymous, category, mood_tag, like_count, comment_count, moderation_status, created_at) values
  ('dc75c9ad-5d0c-4b84-ba8d-293e00d53780', (select id from public.profiles order by random() limit 1), '23 yaşındayım ve üç yıldır evliyim. Kocam 24 yaşında ama cinselliğe hiç yanaşmıyor. Geceleri yanına yaklaşsam bile sürekli yorgunum veya başım ağrıyor gibi mazeretler söylüyor. Başta sorunun bende olduğunu düşünüyordum ama kendime baktığımda genç ve bakımlı olduğumu görüyorum; artık bu durum gururuma dokunuyor. İnternette her gün onlarca kişi bana yazıyor, iltifat ediyor. Bir gün gözümün oraya kaymasından korkuyorum ama bir yandan da istiyorum çünkü içten içe yanıyorum. Onu hâlâ seviyorum ama bu suskunluk beni bitiriyor. Sizce sorun bende mi, yoksa konuşup yüzleşmem mi gerekiyor?', true, 'Aşk', 'Aşk', 1937, 973, 'approved', now() - interval '17349 minutes'),
  ('f9fc15dc-35b6-4355-81b2-ebc001ee5904', (select id from public.profiles order by random() limit 1), 'Geçen akşam eşim bana bu gece için büyük bir sürprizim var, fantezi dünyamızı renklendireceğim dedi. Ben de heyecanla beklemeye başladım. Kapı açıldığında karşıma dantelli bir şeyler çıkacak sanırken, eşim içeriye tam teçhizatlı bir arı kostümüyle girdi. Sırtında şeffaf kanatlar, kafasında sallanan antenler, elinde de bir kavanoz balla bugün kovanın kraliçesi benim diyerek üzerime koşmaya başladı. Gülmekten yatağın altına girdim, o ise bozulup sen benim ruhumu anlamıyorsun diyerek salonda uyumaya gitti. Şu an evde bal kavanozu görsem gülme krizine giriyorum. Bu adamı ciddiye alıp evliliğe nasıl devam edeceğim?', true, 'Fantezi', 'Fantezi', 1782, 137, 'approved', now() - interval '8573 minutes'),
  ('7c23ad26-673a-4039-a88e-f8aafed1cb7f', (select id from public.profiles order by random() limit 1), 'Evlendiğimden beri bana hayatı zindan eden, yemeğimi evimi beğenmeyen kaynanam geçen ay bel fıtığı oldu ve yatağa düştü. Görümcem kaçtı, kocam iş güç derken koskoca kadın benim elime kaldı. Kötülük yapmıyorum, çorbasını veriyorum, ilacını veriyorum ama odaya girerken yavaş yavaş yürüyüp nasıl annecim, beğendin mi yemeği diye soruyorum. Gıkı çıkmıyor, rengi atıyor. Büyük lokma ye büyük konuşma demişler annecim, bak şimdi o beğenmediğin elime muhtaç oldun. İçimin yağları öyle bir eriyor ki anlatamam. Yıllarca çektirdiklerinin acısını böyle mi çıkarıyorum, yoksa ben mi kötü bir insan oldum?', true, 'Aile', 'Aile', 17, 66, 'approved', now() - interval '31406 minutes'),
  ('9f2200b0-2e31-4949-8d11-8a99f95da6df', (select id from public.profiles order by random() limit 1), 'Düğünümde takılan yirmi tam altını kocamdan gizli bozdurup eski sevgilimin kumar borcunu ödedim. Yerine de birebir aynı görünen sahte imitasyon altınları koydum. O zamanlar onu hâlâ unutamamıştım ve yalvardı. Şimdi kocam araba almak için altınları bozduracağız diye tutturdu. Kasayı açarsa biterim, o sahtelerle kuyumcuya giderse rezil oluruz. Evde hırsızlık süsü verip evi dağıtsam polis işin içine girer mi? Hata yaptığımın ben de farkındayım, zaten pişmanım. Ama şimdi bu yalanın altından nasıl kalkacağımı bilmiyorum. Çok sıkıştım, bir akıl verin ne olur.', true, 'Aldatma', 'Aldatma', 134, 91, 'approved', now() - interval '2447 minutes'),
  ('2b954f08-7533-4213-91f9-a1276dc96dd2', (select id from public.profiles order by random() limit 1), 'Eşim son zamanlarda tutturmuş farklı yollardan gidelim diye, sürekli sınırlarımı zorluyor. Ben olmaz, canım yanıyor, yıprandım artık dedikçe, o yeni trend bu, herkes böyle yapıyor diye baskı kuruyor. Sanki evde eşim değil de bir antrenör var, sürekli istemediğim şeylere zorluyor beni. İtiraz edince de beni sevmiyorsun triplerine giriyor, küsüyor. Gerçekten psikolojik olarak da fiziksel olarak da bittim, kendimi çok değersiz hissetmeye başladım. Sırf o mutlu olsun diye kendimi bu kadar hırpalamam normal mi? Lütfen paylaşın, kadınlardan akıl almak istiyorum, ne yapmalıyım?', true, 'Dram', 'Dram', 38, 18, 'approved', now() - interval '24029 minutes'),
  ('2bc6feb4-d6d8-4884-a184-393bb133532b', (select id from public.profiles order by random() limit 1), 'Şanlıurfa''da yaşıyorum. Yıllar önce amcamla yasak bir ilişkim vardı, ondan hamile kaldım. Günden güne karnım sürekli şişiyordu, ailem hamile olduğumu anladı. Önce küfür kıyamet havada uçuştu, şiddet gördüm ama ben hep inkâr ettim. Sonra amcam cinlerden hamile kalmış olabileceğimi söyledi, bir hoca ayarladı, hocaya da gittik, oda aynısını söyledi. Kimseye dillendirmeyin, ben şifasını sağlayacağım dedi, öyle ailemizi inandırdık. Çocuk da düşük oldu. Bu olaydan bir buçuk yıl sonra görücü usulü biriyle evlendim. Şu an iki çocuğum var ve kocam hiçbir şeyden habersiz. İtirafım böyle gizli olsun, içimde taş gibi duruyor.', true, 'Korku', 'Korku', 131, 38, 'approved', now() - interval '32099 minutes'),
  ('c6edb414-6982-46f5-87ad-af09958274d3', (select id from public.profiles order by random() limit 1), 'Lise yıllarımda, ben on yedi yaşındayken okulumuzun müdürüyle çok samimiydik. Ama o evli ve otuz iki yaşındaydı, derslerde beni odasına çağırırdı; o dönemde aramızda hiçbir şey yaşanmadı. Okul bitti, herkes kendi hayatını kurdu. Şu an yirmi iki yaşındayım ve nişanlıyım. Bir gün bana mesaj attı neredesin, neler yapıyorsun diye. Evli olduğunu bildiğim için yanıt vermek istemedim ama dayanamadım ve cevap verdim. O gün gece uzun uzun konuştuk, benimle bir şeyler yaşamak istediğini söyledi. Sonunda ikna oldum ve beraber olduk. Onun eşi, benim nişanlım bundan habersiz. Beni çok şımartıyor ama yaptığımızın ne kadar doğru olduğunu bilmiyorum.', true, 'Aldatma', 'Aldatma', 42, 41, 'approved', now() - interval '20677 minutes'),
  ('36ba9edd-bf4f-4efc-bc65-ed119c2b5023', (select id from public.profiles order by random() limit 1), 'Arkadaşımın sevgilisi yaşından çok büyüktü. Adam annesine istek atmış, annesiyle konuşmuşlar, derken annesiyle çıkmaya başlamış. Bu arada arkadaşımın babası vefat etmişti. Çocuk bize sürekli anlatıyordu, sonra okulda kimseyle konuşmamaya başladı. Bir hafta okula gelmedi, içine kapandı. Sonradan öğrendik; sevgilisiyle annesi ayrılmış, annesi ağlayarak ona her şeyi anlatmış. O olaydan beri çocuk çok değişti, gözlerindeki ışık gitti. Yakın arkadaştık ama sonradan birbirimizi engelledik, şu an konuşmuyoruz. Bu hikâyeyi anlattığından beri unutamıyorum, geceleri aklıma geliyor. İtirafım gizli kalsın.', true, 'Aile', 'Aile', 343, 190, 'approved', now() - interval '21273 minutes'),
  ('98fe63d6-d73d-4187-83de-1b904a1cb6ea', (select id from public.profiles order by random() limit 1), 'Otuz sekiz yaşında, iki çocuk babası bir adamım. Karımla on beş yıllık evliyiz ama son üç yıldır aynı evde iki yabancı gibi yaşıyoruz. Akşam eve geliyorum, o telefonuyla, ben televizyonla. Aynı yatakta sırtımız dönük yatıyoruz. Çocuklar için ayrılmıyoruz ama bu sessizlik beni içten içe öldürüyor. Geçen gün iş yerinde yeni gelen bir kadınla sohbet ettik, yıllar sonra ilk kez biri bana güldü ve umursadı. O akşam eve gelirken arabada ağladım. Aldatmak istemiyorum, böyle biri değilim. Ama bu kadar yalnız bir evlilik mi olur? Çocuklarım büyüyene kadar mı katlanmalıyım, yoksa herkesin canını yakıp ayrılmalı mıyım?', true, 'Dram', 'Dram', 446, 77, 'approved', now() - interval '18029 minutes'),
  ('5c6a19db-b700-4018-a382-e4920c6aef8e', (select id from public.profiles order by random() limit 1), 'Babama hayatım boyunca hiç seni seviyorum diyemedim. Çok sert bir adamdı, hep mesafeli durdum, gururuma yedirdim. Hep yarın derdim, bir gün otururuz konuşuruz derdim. Geçen ay sabaha karşı telefon çaldı, kalp kriziydi, hastaneye yetiştiremedik. Cenazede tek kelime edemedim, sanki taş kesildim. Şimdi her gece mezarının başında saatlerce o üç kelimeyi söylüyorum ama artık duyamıyor. Odasındaki gömleğini koklayarak uyuyorum. Sevdiklerinize söyleyin, gururunuzu bir kenara koyun, çünkü ölüm haber vermeden geliyor. En büyük pişmanlığım bu ve bunu hiçbir şey değiştiremeyecek.', true, 'Pişmanlık', 'Pişmanlık', 1871, 219, 'approved', now() - interval '1315 minutes'),
  ('cb440c0a-d1d7-4745-9886-8e7d3ae721bc', (select id from public.profiles order by random() limit 1), 'Eşim hamileyken, doğuma iki ay kala büyük bir hata yaptım ve eski bir tanıdığımla bir gece geçirdim. O kişiyle her şey o gece bitti, bir daha asla görüşmedik. Eşim hiçbir zaman öğrenmedi, şu an kızımız beş yaşında ve mutlu bir aileyiz. Ama ben her gün bu suçlulukla yaşıyorum. Kızıma sarıldığımda, eşimin gözlerine baktığımda içim parçalanıyor. İtiraf etsem ailem dağılır, çocuğum yuvasız kalır; etmesem bu yük beni içten içe çürütüyor. Bazen rüyalarımda eşim her şeyi öğreniyor ve terden uyanıyorum. Bu sırrı mezara mı götürmeliyim, yoksa dürüst olup her şeyi yıkmalı mıyım?', true, 'Aldatma', 'Aldatma', 114, 99, 'approved', now() - interval '34966 minutes'),
  ('8f616d29-05fb-4f65-98b1-3b081f90ea54', (select id from public.profiles order by random() limit 1), 'On iki yıldır aynı şirkette çalışıyorum ve en sadık eleman benim. Bütün önemli projeleri ben yetiştirdim, gece gündüz demedim. Geçen ay müdürüm, benim aylarca uğraştığım bir projeyi yönetime kendi fikriymiş gibi sundu ve terfiyi, zammı o aldı. Bir şey demedim, içime attım. Sonra onun büyük bir hesap hatası yaptığını fark ettim ama bilerek düzeltmedim, sustum. Şimdi o hata yüzünden şirket büyük bir müşteriyi kaybetti ve fatura ona kesiliyor. İçten içe seviniyorum, oh olsun diyorum. Ama gece yatağa yatınca bu sevincin beni kötü bir insana dönüştürdüğünü düşünüyorum. Bu intikam beni rahatlatmadı, daha da boşalttı. Yanlış mı yaptım?', true, 'İş Hayatı', 'İş Hayatı', 41, 64, 'approved', now() - interval '5755 minutes'),
  ('89ce0b40-3ace-40c4-9743-b5350324c1d4', (select id from public.profiles order by random() limit 1), 'İş yerinde herkesin gözünde dürüstlüğün timsaliyim, kasaya en çok benim güvenilir. Ama geçen ay zor bir döneme girmiştim, borçlarım birikmişti ve kasadan bir miktar para aldım. Sonra açık ortaya çıkınca panikledim ve suçu yeni gelen stajyer çocuğun üstüne yıktım. Çocuk o kadar yalvardı ki ama ben sustum, o kovuldu. Şimdi o para yavaş yavaş cebimden gidiyor ama o çocuğun ağlayan yüzü her gece gözümün önüne geliyor. Sosyal medyada gördüm, hâlâ iş bulamamış. Gidip itiraf etsem hem işimi hem itibarımı kaybederim, etmesem bu vicdan azabıyla bir ömür yaşayacağım. Ne yapacağımı gerçekten bilmiyorum.', true, 'Utanç', 'Utanç', 1947, 986, 'approved', now() - interval '40094 minutes'),
  ('4d117c5b-ac3e-4693-afdb-2c04af16a289', (select id from public.profiles order by random() limit 1), 'Yan komşumuzun evinden geceleri sürekli garip sesler, bir kadının boğuk boğuk ağlaması geliyor. Adam çok asık suratlı, merdivende karşılaşınca selam bile vermiyor. Geçen gece çığlığa benzer bir ses duydum, kalbim ağzıma geldi. Eşime söyledim, sen yine kuruntu yapıyorsun dedi ve uyudu. Ama ben emin değilim, ya o kadına bir şey oluyorsa ve ben sustuğum için bir şey olursa? Müdahale etsem belki yanlış anlaşılır, başımı belaya sokarım; etmesem belki bir canın gitmesine göz yummuş olurum. Polise isimsiz ihbar mı etmeliyim, yoksa kendi işime mi bakmalıyım? Geceleri uyuyamıyorum artık.', true, 'Korku', 'Korku', 375, 84, 'approved', now() - interval '22181 minutes'),
  ('885d9624-214d-4bfd-981c-15f9199711e0', (select id from public.profiles order by random() limit 1), 'Kocam dünyanın en iyi insanı, beni el üstünde tutuyor, hiçbir dediğimi iki etmiyor. Ama ben hâlâ on yıl önce ayrıldığım üniversite aşkımı unutamadım. Sosyal medyada onu gizli bir hesaptan her gün takip ediyorum, fotoğraflarına bakıp bakıp dalıyorum. Geçen gün bana mesaj attı, seni çok özledim dedi ve içimde bir şeyler altüst oldu. Kocama haksızlık ettiğimi, ona ihanet ettiğimi biliyorum çünkü kalbim aslında hâlâ orada. Bu adam bana çiçek alıyor, ben başka birini düşünüyorum. Kendimden tiksiniyorum ama bu duyguyu da bir türlü söküp atamıyorum. Berbat bir insan mıyım, yoksa kalbe söz geçmiyor mu gerçekten?', true, 'Aşk', 'Aşk', 394, 74, 'approved', now() - interval '199 minutes'),
  ('9f422d53-2bab-4b10-8185-f9333deaca9f', (select id from public.profiles order by random() limit 1), 'Yıllar önce çok zor bir dönemimde, otobüste cüzdanımı kaybetmiştim; içinde o ayki kiram, ehliyetim, her şeyim vardı. Eve ağlayarak geldim, mahvolmuştum. İki gün sonra kapım çaldı, yaşlı bir amca cüzdanımı içindeki tek kuruşu eksilmeden getirdi, sadece adresini bulmak için zahmet etmiş. Ona para vermek istedim, almadı, sadece sen de birine iyilik yap dedi ve gitti. O günden beri bulduğum her şeyi sahibine ulaştırıyorum, yardıma muhtaç gördüğüme elimden geleni yapıyorum. O amcayı bir daha hiç görmedim ama hayatımı değiştirdi. İtirafım: insanlığa olan inancımı bir yabancı kurtardı ve ben de o zinciri devam ettirmeye çalışıyorum.', true, 'Diğer', 'Diğer', 83, 17, 'approved', now() - interval '32520 minutes'),
  ('ccdacba9-7675-462f-985a-248159fd456d', (select id from public.profiles order by random() limit 1), 'Eşim kumar batağına saplandı ve fark etmeden ailemizin tüm birikimini, çocuklarımın eğitim parasını bitirdi. Kayınvalidem, kayınpederim hiçbir şeyden haberdar değil, çünkü ben utancımdan örtbas ediyorum, herkese mutluyuz diyorum. Geçen gün son olarak bir kenara sakladığım altınları da bulup götürdü. Onu hâlâ seviyorum, çocuklarımın babası ne de olsa, ama artık nefes alamıyorum, geceleri tavanı izleyerek ağlıyorum. Ona her bir şey diyemiyorum çünkü borç batağındayken bir de onu kaybetmekten korkuyorum. Bu evi nasıl kurtarırım, bu adamı nasıl bu bataktan çekip çıkarırım, gerçekten çaresizim. Bir yol gösterin lütfen.', true, 'Dram', 'Dram', 2228, 146, 'approved', now() - interval '14997 minutes'),
  ('d6107f9f-fa5a-4d1e-b0e1-f2626e36c04f', (select id from public.profiles order by random() limit 1), 'Annem ölmeden bir gün önce beni yanına çağırdı ve titreyen elleriyle bir sır verdi: yıllardır ağabeyim diye bildiğim kişi aslında üvey kardeşimmiş, babamın ilk evliliğinden. Kimse bilmiyor, ağabeyim bile. Annem bunu yıllarca taşımış, ölürken bana devretti. Şimdi her aile toplantısında ona baktığımda bu sır boğazıma düğümleniyor, gülerken bile içim titriyor. Söylesem belki ailemiz dağılır, ağabeyim yıkılır, babama olan güveni biter; söylemesem bu yükü tek başıma bir ömür taşıyacağım. Annemin son isteği gizli kalmasıydı ama bu doğru mu, emin değilim. Bazen sırlar insanı içten içe yiyor.', true, 'Aile', 'Aile', 956, 97, 'approved', now() - interval '11450 minutes'),
  ('346302bf-a2ac-43e5-8af0-f12ad58226ea', (select id from public.profiles order by random() limit 1), 'Gençken çok severdim bir adamı, evlenecektik. Ama ailem onu istemedi, fakir diye burun kıvırdılar ve ben de onların hatırı için, biraz da inadına ondan vazgeçtim. O da kırıldı, çekip gitti, başka şehirde evlendi. Şimdi kırk beş yaşındayım, ailemin istediği zengin adamla evlendim ama o evde bir gün bile mutlu olmadım, sadece odalar ve eşyalar içinde yalnızım. Geçen hafta onu bir düğünde gördüm, yanında karısı, torunları, kahkahalar... Eve gelip gece yarısına kadar ağladım. Keşke o gün biraz daha cesur olsaymışım, keşke kalbimi dinleseymişim. Para mutluluk getirmedi, sadece pişmanlığımı süsledi.', true, 'Pişmanlık', 'Pişmanlık', 362, 184, 'approved', now() - interval '37295 minutes'),
  ('4ad85f44-12c0-44ff-ab11-349da530183b', (select id from public.profiles order by random() limit 1), 'Eşimin telefonunda, yıllardır devam eden bir yazışma buldum. Eski sevgilisiyle her gün mesajlaşıyorlar, günaydın diyorlar, gününü anlatıyorlar, sıkıntısını paylaşıyorlar. Fiziksel hiçbir şey yok, ama o kadına benimle paylaşmadığı şeyleri anlatıyor, kalbi orada. Bunu söylesem sadece arkadaşız, abartıyorsun diyecek, beni kıskanç ilan edecek. Ama ben gece yanımda yatan adamın aklının başka yerde olduğunu biliyorum. Aldatmak sadece fiziksel mi olur, yoksa kalbini, sırlarını başkasına vermek de aldatmak mı? Kanıtım var ama yüzleşmeye korkuyorum, çünkü cevabı duymaktan ödüm kopuyor. Sizce ben paranoyak mıyım, yoksa haklı mıyım?', true, 'Aldatma', 'Aldatma', 2811, 298, 'approved', now() - interval '9462 minutes'),
  ('90cffa1a-3fb0-461f-9417-a69d096cf716', (select id from public.profiles order by random() limit 1), 'Üniversitede bitirme projemi internetten buldum, birkaç kelimesini değiştirip kendiminmiş gibi sundum. Hocalar fark etmedi, hatta en yüksek notu aldım, herkes beni tebrik etti. Şimdi tam da o alanda, iyi bir şirkette çalışıyorum. Ama her toplantıda, her sunumda içimde bir yerlerden ya birileri o eski projeyi hatırlarsa, ya yakalanırsam korkusu yükseliyor. Koca bir kariyeri tek bir yalanın üstüne kurdum ve o yalan beni gölgesi gibi takip ediyor. Bazen her şeyi bırakıp baştan, dürüstçe başlamak istiyorum ama o zaman da bu hayatı kaybetmekten korkuyorum. Bir yalan insanı ömür boyu nasıl da esir alıyormuş, keşke o gün dürüst olsaymışım.', true, 'Okul', 'Okul', 21, 47, 'approved', now() - interval '15137 minutes'),
  ('e9f4c64a-b9c0-49ca-bb4a-f9b11dd06c52', (select id from public.profiles order by random() limit 1), 'Eşim aşırı kıskanç, telefonumu, mesajlarımı, nereye gittiğimi, kiminle konuştuğumu sürekli kontrol ediyor. Başta beni seviyor, sahipleniyor diye düşünüyordum, hoşuma bile gidiyordu. Ama artık arkadaşlarımla görüşemiyorum, makyaj yapsam kime süsleniyorsun diye sorguya çekiliyorum, geç kalsam telefonu kilitliyor. Ayrılmaktan söz etsem sensiz yaşayamam, kendime bir şey yaparım diye tehdit ediyor. Korkuyorum, hem ondan hem de yalnız kalmaktan. Ailem boşanmaya karşı, kınanmaktan çekiniyorum. Bu bir sevgi değil, kafes; bunu biliyorum ama nasıl çıkacağımı bilemiyorum. Aynı şeyi yaşayan var mı, ne yaptınız?', true, 'Korku', 'Korku', 162, 47, 'approved', now() - interval '37858 minutes'),
  ('85697fc1-c834-47e5-be33-7536a83e6829', (select id from public.profiles order by random() limit 1), 'Görücü usulü, eşimi düğünden önce sadece iki kez görerek evlendim. İlk yıl gerçekten çok zorlandım, bir yabancıyla aynı yatağı, aynı sofrayı paylaşmak korkunçtu, çok ağladım. Ama yıllar geçtikçe bu yabancı benim en yakınım, sırdaşım, can yoldaşım oldu. Komik olan, gençken asla görücü usulü evlenmem, ben aşkı bulacağım derdim, bu fikirle dalga geçerdim. Geçen ay ben hastanede yatarken başucumdan hiç ayrılmadı, elimi tuttu, ben uyuyana kadar bekledi. O an anladım ki aşk dediğimiz şey filmlerdeki gibi gümbür gümbür gelmek zorunda değilmiş, bazen sessizce, yavaş yavaş büyüyormuş. İtirafım bu: en beklemediğim yerde mutluluğu buldum.', true, 'Aşk', 'Aşk', 286, 77, 'approved', now() - interval '8121 minutes'),
  ('64ecc228-c48b-4e21-b6f7-6d71bb3352ae', (select id from public.profiles order by random() limit 1), 'Eşim altı ay önce işten çıkarıldı ve o günden beri evin tüm yükü benim omuzlarımda. Sabah erken çıkıyorum, akşam bitap dönüyorum, üstüne ev işleri, çocuklar... Ona tek bir kelime sitem etmedim, yüzüne vurmadım. Ama o gururundan, ezilmişlik hissinden bana karşı bambaşka biri oldu; soğuk, sinirli, içine kapanık. Yardım etmek, ona iş bulması için destek olmak istiyorum ama her teklifimi acıma sanıp reddediyor, daha da uzaklaşıyor. İkimiz de mutsuzuz, aynı evde iki yorgun yabancı gibiyiz. Onu seviyorum ama sevgi tek başına yetmiyor galiba. Bu dönem geçer mi, yoksa bu evlilik bu yükün altında ezilip gider mi, korkuyorum.', true, 'Dram', 'Dram', 7902, 966, 'approved', now() - interval '7610 minutes'),
  ('27534722-362f-40bb-9576-3cdb2c5938b4', (select id from public.profiles order by random() limit 1), 'Çok zor bir günümde, kirayı ödeyemeyecek durumdayken, en güvendiğim arkadaşımdan borç istedim. Bin bir bahaneyle vermedi, beni o gün geri çevirdi. Aradan bir yıl geçti, benim durumum düzeldi, onunki bozuldu ve bir gün gelip benden yardım istedi. Ben de tıpatıp aynı sözleri söyleyip geri çevirdim, intikamımı aldım. O an haklı çıkmanın keyfini bekliyordum ama hiç tatmin olmadım, sadece içim daha da boşaldı, kendimi onun kadar küçük hissettim. Demek ki kötülüğe kötülükle karşılık vermek insanı iyileştirmiyor, sadece onun seviyesine indiriyormuş. Keşke ben farklı davranıp daha iyi bir insan olabilseymişim. Hâlâ o günün utancını taşıyorum.', true, 'Utanç', 'Utanç', 138, 8, 'approved', now() - interval '13344 minutes'),
  ('e7f8e790-e28f-4bc8-9752-bd3f23d755bf', (select id from public.profiles order by random() limit 1), 'Babam vefat etti ve mirası paylaşırken kardeşlerim bana en küçük payı uygun gördüler; sen zaten iyi kazanıyorsun, sana ihtiyaç yok dediler. Aslında o evi, o tarlayı babamla en çok ben ilgilenirdim, hasta yatağında aylarca başında ben bekledim. İtiraz etmedim, kavga çıkmasın diye sustum ama o gün içimde bir şey koptu. Mesele para değildi, değer görmemekti, emeğimin yok sayılmasıydı. O günden beri kardeşlerimle konuşmuyorum, bayramlarda aramıyorlar, ben de aramıyorum. Babam sağ olsa buna çok üzülürdü. Haklı mıyım, yoksa gururuma yenik düşüp ailemi mi kaybediyorum, artık bilmiyorum.', true, 'Aile', 'Aile', 426, 152, 'approved', now() - interval '4655 minutes'),
  ('c6db912b-823a-4433-bdf2-ff70a5bb9ebe', (select id from public.profiles order by random() limit 1), 'İlk çocuğum doğduğunda çok genç ve hazırlıksızdım, üstüne ağır bir depresyona girdim. O dönem oğluma yeterince sarılamadım, gülemedim, ona soğuk davrandım çünkü kendi karanlığımla boğuşuyordum. Şimdi o on beş yaşında ve benimle arasına kalın bir duvar örmüş; ne sarılıyor, ne dert anlatıyor, gözümün içine bakmıyor. Telafi etmek için çırpınıyorum ama o duvarı bir türlü aşamıyorum, sanki çok geç kaldım. Keşke o zamanlar yardım isteseymişim, keşke daha güçlü olabilseymişim. Bir annenin en büyük korkusu çocuğunun gözündeki o uzaklık. Bu pişmanlık beni her gece içten içe yiyor. Bu duvarı yıkmanın bir yolu var mı?', true, 'Pişmanlık', 'Pişmanlık', 2831, 742, 'approved', now() - interval '32782 minutes'),
  ('106d8158-d53b-497f-9584-7c4f3934b522', (select id from public.profiles order by random() limit 1), 'Bekarlığa veda gecemde, düğünüme bir hafta kala büyük bir hata yaptım. O gece olanları kimse bilmiyor, eşim bile, ve biz şu an herkesin imrendiği mutlu bir çiftiz. Ama her evlilik yıldönümümüzde, o güzel anın tam ortasında, o gece aklıma geliyor ve gülümsemem bir anda donuyor. Eşim neyin var diye soruyor, ben bir şeyim yok aşkım diyorum ama içim kan ağlıyor. Bu sırrı bir ömür taşımak çok ağır, bazen patlayıp her şeyi anlatasım geliyor. Ama itiraf etmek dürüstlük mü olur, yoksa sadece kendi vicdanımı rahatlatmak için onun dünyasını mı yıkarım? Susmak mı, konuşmak mı; hangisi daha az kötü, gerçekten bilmiyorum.', true, 'Aldatma', 'Aldatma', 429, 100, 'approved', now() - interval '2620 minutes'),
  ('01cb9dfd-64c1-49e9-961a-a00455847c3a', (select id from public.profiles order by random() limit 1), 'En dibe vurduğum, hayata küstüğüm bir dönemde sokakta titreyen bir köpek yavrusu buldum ve eve aldım. Herkes deli misin, başına iş açacaksın, sorumluluk bu dedi. Ama o küçük canlı, kimsenin olmadığı en karanlık gecelerimde yanımda oldu, ben ağlarken başını dizime koydu. Bana koşulsuz sevmeyi, hiçbir şey beklemeden var olmayı öğretti. İşten kovulduğumda, terk edildiğimde, hep o kapıda kuyruğunu sallayarak bekledi. Bazen en sadık dostlar dört ayaklı oluyor, insanlar terk ediyor ama o asla. İtirafım şu: bugün ayakta olmamı, hayata tutunmamı bir sokak köpeğine borçluyum ve onsuz bir hayat artık düşünemiyorum.', true, 'Diğer', 'Diğer', 989, 524, 'approved', now() - interval '39664 minutes'),
  ('5c68b6b5-7646-4a59-bf8e-3d2e747e803e', (select id from public.profiles order by random() limit 1), 'Annem ben çocukken hep kardeşimi kayırdı, onu överdi, beni hep onunla kıyasladı. Yıllarca senin kardeşin gibi olamadın cümlesini duya duya büyüdüm, içimde kocaman bir öfke birikti. Geçen ay kardeşim zor duruma düşüp benden borç istedi, param vardı ama yok dedim, ilk defa hayır diyebildim. O an garip bir rahatlama, bir zafer hissi yaşadım. Ama akşam yatağa yatınca o his yerini tiksintiye bıraktı, ben de tıpkı onların beni ittiği o kötü yere düştüm. Çocukluğumun acısını kardeşimden çıkarmak beni iyileştirmedi, sadece annemin yaptığını tekrarlayan biri yaptı. Bu kin normal mi, yoksa ben de mi onlar gibi oluyorum?', true, 'Aile', 'Aile', 128, 7, 'approved', now() - interval '3181 minutes'),
  ('0835405a-954e-41ee-9c52-1848e39fa0af', (select id from public.profiles order by random() limit 1), 'Apartmanımıza yeni taşınan komşu, eşim işteyken sürekli bahaneyle kapımı çalıyor; tuz isteyeceğim, internet şifreni alabilir miyim derken garip garip içeri bakıyor, gözleri üzerimde geziyor. Eşime anlattım, sen yine vehme kapılmışsın, adam iyi niyetli dedi. Ama ben gündüzleri evde yalnızken artık huzursuzum, kapıyı çift kilitliyorum, perdeleri kapatıyorum. Belki gerçekten bir şey yok, belki paranoyak oluyorum ama içimdeki o tedirginlik geçmiyor. Taşınmayı bile düşünüyorum ama eşim abarttığımı söylüyor. Bir kadının içgüdüsü genelde yanılmaz derler. Sizce kuruntu mu yapıyorum, yoksa ciddiye mi almalıyım? Çok korkuyorum.', true, 'Korku', 'Korku', 45, 47, 'approved', now() - interval '23340 minutes'),
  ('828a05f1-772e-45a2-a602-08485b8f7a87', (select id from public.profiles order by random() limit 1), 'Yirmi yıldır aynı kurumda dişimle tırnağımla çalıştım, emekliliğime bir yıl kaldı. Geçen ay otuz yaşında, daha yeni gelmiş bir yönetici beni odasına çağırdı ve verimsizsin, çağı yakalayamıyorsun diyerek istifaya zorladı. Bir ömrümü verdiğim yerde, gencecik birinin karşısında küçük düşürüldüm, ellerim titredi, eve gelip ilk defa eşimin önünde ağladım. Sessizce, gururumu koruyarak çekip gitmek mi, yoksa hukukçu tutup hakkımı sonuna kadar aramak ve belki de itibarımı kurtarmak mı? Sessizlik onların ekmeğine yağ sürer ama mücadele de beni yıpratır. Bu yaştan sonra bu kavgayı verecek gücüm var mı, emin değilim. Ne yapardınız?', true, 'İş Hayatı', 'İş Hayatı', 1051, 151, 'approved', now() - interval '31776 minutes'),
  ('cc302a86-1e25-47fa-81b1-152eee1f2dc7', (select id from public.profiles order by random() limit 1), 'İnternette bir oyun üzerinden tanıştığım biriyle iki yıldır her gün konuşuyoruz, hiç yüz yüze görüşmedik ama onu hayatımdaki herkesten çok seviyorum. Sabah onun mesajıyla uyanıyorum, gece onunla uyuyorum, en derin sırlarımı sadece o biliyor. Ailem tanımadığın, yüzünü görmediğin biri olur mu, kandırılırsın diyor ve haklı olabilirler. Yarın ilk kez gerçekten buluşacağız, başka bir şehre gidiyorum ve ödüm kopuyor. Ya hayal ettiğim kişi değilse, ya bu güzel duygu bir anda yıkılırsa? İki yıllık bir bağ tek bir buluşmada bitebilir mi? Hem çok heyecanlıyım hem de kaçıp saklanmak istiyorum. Bu riske değer mi sizce?', true, 'Aşk', 'Aşk', 289, 123, 'approved', now() - interval '17280 minutes'),
  ('5029e24a-4685-40d0-a0ae-7d2b4fa0ad7c', (select id from public.profiles order by random() limit 1), 'Kayınvalidemle aynı evde yaşıyoruz ve eşim her tartışmada gözünü kırpmadan onun tarafını tutuyor. Kendi evimde misafir gibiyim; mutfağa karışılıyor, çocuğumun nasıl büyütüleceğine karışılıyor, kıyafetime bile laf ediliyor. Geçen gün dayanamayıp eşime ya annen ya ben demenin eşiğine geldim ama korktum, çünkü cevabını duymaktan korktum, belki de annesini seçecekti. Şimdi her gün dişimi sıkıyorum, içime atıyorum ve yavaş yavaş tükeniyorum, kendi evimde nefes alamıyorum. Bu evi bırakıp gitmek mi, yoksa katlanmaya devam edip kendimi kaybetmek mi? Eşimi seviyorum ama bu üçüncü kişiyle bir evlilik yürür mü, artık emin değilim.', true, 'Dram', 'Dram', 187, 32, 'approved', now() - interval '31808 minutes'),
  ('82190b4e-3ddf-4e05-b743-1e110c719db1', (select id from public.profiles order by random() limit 1), 'Toplu taşımada, kalabalık bir otobüste yaşlı bir teyze birden yere düştü. Herkes baktı, telefonlar çekti ama kimse kalkmadı, ben de o an donup kaldım, yerimden kıpırdayamadım. Sonra bir genç koşup teyzeyi kaldırdı, su uzattı. O an neden hareket edemediğimi, neden o gence ben olamadığımı hâlâ anlamış değilim. Eve geldiğimde utancımdan saatlerce ağladım, kendime tiksinerek baktım. Hep iyi bir insan olduğumu düşünürdüm ama o an en küçük iyiliği bile yapamadım. Demek ki insanın gerçek yüzü en beklenmedik anda, en zor anda ortaya çıkıyormuş. O teyzeden, o gençten ve kendimden özür diliyorum. Bu utanç içimde.', true, 'Utanç', 'Utanç', 49, 44, 'approved', now() - interval '6822 minutes'),
  ('f18457d7-dcf6-4b6c-8995-4ce2fa90e773', (select id from public.profiles order by random() limit 1), 'Kocam beni bir kez aldattı, telefonundan öğrendim, dünyam başıma yıkıldı. Ama iki küçük çocuğumuz var, ailem dağılmasın diye dişimi sıktım ve affettim, herkese hiçbir şey olmamış gibi davrandım. Sosyal medyada mutlu aile pozları veriyoruz, herkes bize imreniyor. Ama içimde o güven bir daha asla yerine gelmedi; her gece yanımda yatarken sanki bir yabancıyla uyuyorum, telefonu çaldığında kalbim hızlanıyor, geç kaldığında içim daralıyor. Onu affettim ama unutamadım, ve bu yarı yaşam beni içten içe bitiriyor. Çocuklarım için katlanıyorum ama bu mu doğru olan, yoksa kendime mi ihanet ediyorum? Affetmek bazen en ağır cezaymış.', true, 'Aldatma', 'Aldatma', 29, 35, 'approved', now() - interval '37723 minutes'),
  ('9d9589da-fa62-4a92-904a-98e5d1d7f06f', (select id from public.profiles order by random() limit 1), 'Lise aşkımla evlenecektik, birbirimize söz vermiştik. Ama ben kariyerim için, daha iyi bir gelecek için başka bir şehre, başka bir ülkeye gittim ve mesafe bizi yavaş yavaş bitirdi. Şimdi gerçekten başarılıyım, herkesin imrendiği bir kariyerim, param, unvanım var. Ama her gece bomboş, lüks bir evde yapayalnız uyuyorum, başarımı paylaşacak kimsem yok. O ise sade ama sımsıcak bir aile kurmuş, fotoğraflarında hep gülüyor. Başarı geldi ama mutluluk çoktan gitti. O gün doğru seçimi mi yaptım, yoksa hayatımın aşkını bir unvan uğruna mı feda ettim, hâlâ bilmiyorum. Geceleri en çok bu soru beni uyutmuyor.', true, 'Pişmanlık', 'Pişmanlık', 1118, 78, 'approved', now() - interval '27647 minutes'),
  ('799d4382-0bc5-43b3-8d9d-3a3d15617ba8', (select id from public.profiles order by random() limit 1), 'Eşimle çocuğumuzun önünde sürekli kavga ediyoruz, para, kaynana, yorgunluk derken bağırıyoruz, kapı çarpıyoruz. Geçen gün altı yaşındaki kızım odamıza geldi, gözleri dolu dolu keşke ayrılsanız, ben de arkadaşım gibi iki evde yaşarım dedi. O cümle kalbime bir bıçak gibi saplandı, o gece sabaha kadar uyuyamadım. İkimiz de inatçıyız, kimse pes etmiyor, hep haklı çıkmaya çalışıyoruz ama bu savaşın en büyük kaybedeni o minik kız. Onun için katlanmaya çalışıyorum ama bu kavgalı ev mi, yoksa ayrı ama huzurlu iki ev mi ona daha az zarar verir, gerçekten bilemiyorum. Bir çocuğa bunu yaşatmak için kendimi affedemiyorum.', true, 'Aile', 'Aile', 42, 50, 'approved', now() - interval '27361 minutes'),
  ('5c83fe88-ac93-4edb-85c5-1f86472324ca', (select id from public.profiles order by random() limit 1), 'Her gece neredeyse aynı kâbusu görüyorum: karanlık bir yolda eşim arabasıyla bir uçuruma doğru gidiyor, ben arkasından bağırıyorum ama sesim çıkmıyor, koşuyorum ama yetişemiyorum ve son anda gözlerimi açıyorum, tüm vücudum ter içinde, kalbim deli gibi atıyor. Bunu eşime anlatamıyorum, beni saçma sapan vehimlerle uğraşan biri sanır. Ama bu rüya o kadar gerçekçi ki, sanki bir uyarı, bir önsezi gibi. Onu arabaya bindirirken bile içim titriyor, dikkatli ol diye tembihliyorum. Bilime inanırım, rüya rüyadır derim ama içimdeki bu korkuyu da bir türlü yatıştıramıyorum. Bu sadece bir kâbus mu, yoksa ciddiye mi almalıyım?', true, 'Korku', 'Korku', 302, 24, 'approved', now() - interval '36025 minutes'),
  ('3ffefc05-56e1-40b1-bf2f-4ab245e7e361', (select id from public.profiles order by random() limit 1), 'Eşim yemeklerimi hep över ama bir gün annesinin tarifiyle aynı yapmamı istedi ısrarla. Ben de gizlice annesini arayıp tarifi aldım, üstüne kendi hünerimi de kattım ve harika bir yemek çıktı. Akşam masaya koydum, eşim ilk lokmada gözleri doldu ve tam annemin elinden çıkmış gibi dedi. Tam gururlanıyordum ki annesi sürpriz yapıp kapıya geldi, yemeği gördü ve bu benim tarifim değil ki, sen nereden öğrendin dedi. Eşim şaşkın, ben kıpkırmızı... Meğer annesi bana yanlış tarif vermiş, beni test etmiş. Şimdi kaynanam her fırsatta o tarif olayını anlatıp gülüyor. En masum yalanım bile beni ele verdi, artık mutfakta bir adım önde olmaya çalışıyorum.', true, 'Komik', 'Komik', 129, 40, 'approved', now() - interval '13017 minutes'),
  ('a5d4d5b9-b803-43fc-aa92-e568298c25ff', (select id from public.profiles order by random() limit 1), 'Eşim çok kıskanç olduğu için nişanlıyken bütün eski fotoğraflarımı sildim, arkadaşlarımın çoğuyla bağımı kopardım, sevdiğim bir işi bıraktım, hatta gülüşümü bile ona göre ayarlar oldum. Onu mutlu etmek için kendimden taviz verdim, verdim, verdim. Şimdi düğüne üç ay kaldı ve aynaya baktığımda kendimi tanıyamıyorum; eski neşeli, özgür ben yok olmuş, yerine sürekli izin isteyen, korkan biri gelmiş. Onu seviyorum ama o eski beni de çok özlüyorum. Bu daha evlenmeden böyleyse, evlendikten sonra ne olur? Düzelir diye umut mu etmeliyim, yoksa daha kötüye gitmeden kaçmalı mıyım? Kafam çok karışık, içim daralıyor.', true, 'Aldatma', 'Aldatma', 239, 52, 'approved', now() - interval '7781 minutes'),
  ('d9a543ae-f5d9-4212-b1b3-508931edfe60', (select id from public.profiles order by random() limit 1), 'Patronum maaşları her ay üç beş gün geciktiriyor, biz idare ediyoruz diye sızlanırken o her birkaç ayda bir yeni araba değiştiriyor, lüks tatil paylaşıyor. Bir gün dayanamadım, tüm ekibe haklarımızı, rakamları açıkça anlattım ve toplu bir şekilde istifa dilekçemizi verdik. Patron şoke oldu, ekibin tamamı gidince işler altüst oldu. Şu an işsizim, geleceğim belirsiz, biraz da korkuyorum ama vicdanım çok rahat, başım dik. Bazen doğru olanı yapmak en zor ve en pahalı olandır. Pişman değilim, sadece bu cesaretin bedelini ödeyene kadar dişimi sıkmam gerek. Ezilmeye devam etmektense onurumla işsiz kalmayı seçtim, yanlış mı yaptım sizce?', true, 'İş Hayatı', 'İş Hayatı', 762, 180, 'approved', now() - interval '17533 minutes'),
  ('e98a9f47-a11c-44d5-bfd4-fafec9845cb1', (select id from public.profiles order by random() limit 1), 'Arkadaş grubumuzda yıllardır şakanın, dalganın hedefi hep ben olurum; kilom, işim, sevgilim... Gülüp geçiyorum ama her seferinde içimde bir yer daha kırılıyor, eve gelince sessizce o cümleleri tekrar tekrar düşünüyorum. Geçen gün, sırf ben de güçlü görüneyim diye, gruptaki sessiz bir arkadaşımla aynı şekilde dalga geçtim, herkes güldü. Ama onun yüzündeki o donuk ifadeyi görünce yıllardır benim ne hissettiğimi anladım ve dünya başıma yıkıldı. Demek ki kırgınlık insanı kötülüğe sürüklüyor, ben de bir anda zalim oldum. Hemen özür diledim ama içim hâlâ rahat değil. Bir acı, başka bir acıyla dinmiyormuş. Keşke hiç o kelimeleri söylemeseymişim.', true, 'Utanç', 'Utanç', 665, 94, 'approved', now() - interval '38788 minutes'),
  ('3a20816c-e2b4-420c-b142-98f3f93111dc', (select id from public.profiles order by random() limit 1), 'Çocuğum okulda son zamanlarda sürekli kavga ediyor, arkadaşlarına vuruyor, öğretmeni beni acil çağırdı. Konuşunca anladım ki evde benim ve eşimin sürekli bağırışmalarımızdan, kapı çarpmalarımızdan etkileniyor, öfkeyi bizden öğreniyor. Eşimle çocuğun önünde tartışmayalım diye söz verdik ama bir türlü beceremiyoruz, gerginlik bir bakıyoruz patlamış. En çok da masum bir çocuğun ruhunu kirlettiğimiz için kendimi affedemiyorum, o bizim hatamızın bedelini ödüyor. Bir psikoloğa gitsek mi, ayrı mı yaşasak, ne yapsak da o çocuğa zarar vermesek? Onun o öfkeli küçük yüzünü gördükçe içim parçalanıyor. Bu döngüyü nasıl kırarım?', true, 'Aile', 'Aile', 246, 14, 'approved', now() - interval '36062 minutes'),
  ('09719ce3-929d-4e13-8159-61afa5d81a7c', (select id from public.profiles order by random() limit 1), 'Eşim büyük bir borca girmiş, aylarca benden sakladı; bir gün kapıya icra geldiğinde öğrendim her şeyi. Evi satmak zorunda kaldık, çocuklarım kendi odalarından, oyuncaklarından oldu, küçük bir kiralık eve taşındık. Ona çok kızgınım, neden söylemedin, neden bana güvenmedin diye içim yanıyor. Ama bir yandan da onu bırakıp gidemiyorum çünkü o da çaresiz, o da utanç içinde ve aslında bana, ben de ona muhtacım. Sıfırdan, hiçbir şeyimiz yokken yeniden başlamak mümkün mü gerçekten? Bazı geceler pes etmek istiyorum ama çocuklarımın yüzüne bakınca toparlanıyorum. Bu çukurdan birlikte çıkabilir miyiz, yoksa bu yük bizi koparır mı? Çok yorgunum.', true, 'Dram', 'Dram', 425, 28, 'approved', now() - interval '22668 minutes'),
  ('110fb541-1e74-4f70-a8ad-4eb49d62ed12', (select id from public.profiles order by random() limit 1), 'Eşimle on beş yıllık evliyiz ve ilişkimizde filmlerdeki gibi tutkulu, alev alev bir aşk hiç olmadı, daha çok derin bir dostluk, bir alışkanlık, bir huzur var. Bazen başkalarının büyük aşklarını görünce ben hayatımın aşkını kaçırdım mı, eksik mi yaşıyorum diye düşünüp hüzünleniyorum. Ama geçen ay ben ciddi bir ameliyat geçirdim ve o günlerce hastanede başucumdan ayrılmadı, uyumadı, elimi bıraktığında uyanıyordum. O an anladım ki gerçek sevgi bağıra çağıra gelmek zorunda değilmiş; bazen sessizce, hiçbir şey beklemeden başucunda bekleyen o eldeymiş. Bizimki destansı değil belki ama gerçek, sağlam ve sıcak. İtirafım: yıllarca aradığım şey hep yanı başımdaymış.', true, 'Aşk', 'Aşk', 730, 69, 'approved', now() - interval '270 minutes'),
  ('b64b9261-1734-4742-99da-2c6961a040c2', (select id from public.profiles order by random() limit 1), 'Anneme ergenlik yıllarımda yıllarca sen beni anlamıyorsun, hayatımı mahvediyorsun diye bağırdım, odamın kapısını yüzüne kapattım, onu hep itip kakaladım. O ise her seferinde sessizce arkamdan ağladı ama bir gün bile beni bırakmadı. Şimdi ben de bir anne oldum ve gecelerce uyumadan büyüttüğüm çocuğuma bakarken, annemin neler çektiğini, ne fedakârlıklar yaptığını çok geç anlıyorum. Telefonu açıp özür dilemek, sana çok haksızlık ettim demek istiyorum ama o lanet gururum bir türlü izin vermiyor, kelimeler boğazımda düğümleniyor. Ya bir gün geç kalırsam? Bu inadı kırmak neden bu kadar zor, neden en çok sevdiklerimize en zor özür diliyoruz?', true, 'Pişmanlık', 'Pişmanlık', 1021, 142, 'approved', now() - interval '40046 minutes'),
  ('c4d8f05e-6988-41c8-a928-05bf07414bf4', (select id from public.profiles order by random() limit 1), 'Eşimle yeni bir eve taşındık ve ilk geceden beri evde garip şeyler oluyor; kapılar kendiliğinden gıcırdıyor, geceleri salonda ayak sesleri duyuyorum, koridorda bir an birinin durduğunu hissediyorum. Eşim hep ev eski, ahşap genleşiyor diyerek beni sakinleştiriyor ama dün gece uyandığımda yatağın ucunda bir gölge gördüm ve donup kaldım, bağıramadım bile. Mantıklı biriyim, hayalete falan inanmam, her şeyin bir açıklaması vardır derim. Ama bu evde içimi saran o soğukluğu, o tedirginliği bir türlü açıklayamıyorum. Taşınalı daha bir ay oldu, kira sözleşmesi bir yıllık. Kuruntu mu yapıyorum, yoksa bu evde gerçekten bir terslik mi var? Geceleri uyuyamıyorum artık.', true, 'Korku', 'Korku', 1105, 446, 'approved', now() - interval '13784 minutes'),
  ('a4d43aec-c7f7-4c17-adaf-cbbd635ffa69', (select id from public.profiles order by random() limit 1), 'Yıllarca herkesin onayını almak için yaşadım; ailemin istediği bölümü okudum, onların seçtiği işe girdim, beklentilere göre giyindim, konuştum, hatta güldüm. Bir gün aynada kendime baktım ve karşımdaki kişiyi hiç tanımadığımı fark ettim, kendi hayatımda bir misafir gibiydim. O gün her şeyi bıraktım; istemediğim işten ayrıldım, gerçekten sevdiğim, herkesin saçmaladığını söylediği o hayali peşinden gittim. Herkes deli oldun dedi, sıfırdan başladım, çok zorlandım, aç kaldığım günler oldu. Ama hayatımda ilk kez sabah gözlerimi kendi istediğim hayata açtım. İtirafım: başkaları için yaşadığım otuz yılı geri istiyorum ama en azından kalanını kendim için yaşayacağım.', true, 'Diğer', 'Diğer', 304, 26, 'approved', now() - interval '16700 minutes'),
  ('3d2f185d-3665-4a44-b9f8-4a74ee504ed9', (select id from public.profiles order by random() limit 1), 'Üniversitede bir hocaya, çok zekiydi, çok karizmatikti, gizliden gizliye âşık oldum. Aramızda asla uygunsuz hiçbir şey yaşanmadı, o profesyonelliğini hiç bozmadı, ben de tek kelime etmedim, sadece derslerini iple çektim, her bakışını biriktirdim. Mezun oldum, yıllar geçti, ben başka biriyle evlendim, çocuklarım oldu, mutlu bir hayatım var. Ama geçen gün bir kongrede onu yıllar sonra gördüğümde, kalbim yine yirmi yaşımdaki gibi küt küt attı ve dizlerimin bağı çözüldü. Hiçbir şey yapmadım, yapmayı da düşünmüyorum, eşimi seviyorum. Sadece bazı duygular hiç ölmüyormuş, bir köşede usulca bekliyormuş. İtirafım bu, kimseye söyleyemediğim küçük bir sırrım.', true, 'Aşk', 'Aşk', 113, 2, 'approved', now() - interval '11485 minutes'),
  ('53531a64-9627-4858-a680-8e5b5becfa0f', (select id from public.profiles order by random() limit 1), 'Kocam iş seyahatindeyken telefonuna bir mesaj düştü ve ben yanlışlıkla gördüm; başka bir kadınla aylardır süren, çok samimi bir yazışma. Ne yapacağımı bilemedim, bağırmadım, ağlamadım, hiç belli etmedim. Sanki hiçbir şey bilmiyormuşum gibi davranıyorum, ona gülümsüyorum, yemeğini yapıyorum ama bir yandan da sessizce kanıt topluyorum, ekran görüntüleri alıyorum. Bir avukatla görüştüm bile. Ona güvenen, onun için her şeyi bırakan bendim ve şimdi kendi evimde bir dedektif gibiyim, kendime acıyorum. Yüzleşmek mi, yoksa her şeyi sağlama alıp tek hamlede mi bitirmeli? Bu sessiz bekleyiş beni içten içe zehirliyor ama ona koz vermek de istemiyorum. Ne yapardınız?', true, 'Aldatma', 'Aldatma', 2827, 165, 'approved', now() - interval '14158 minutes'),
  ('da726b2c-487d-4794-af94-4d6ab5da7af7', (select id from public.profiles order by random() limit 1), 'Babam ben küçükken bizi bırakıp başka bir kadına gitti, annem beni türlü zorlukla, gece gündüz çalışarak tek başına büyüttü. Yıllarca babama içimde kocaman bir öfke besledim, adını bile anmadım. Geçen hafta yabancı bir numaradan aradı; sesi titriyordu, hastayım, yalnızım, yanımda kimse kalmadı, seni görmek istiyorum dedi. Annem sakın gitme, o sana bunu yaşatandı diyor ve çok haklı. Ama bir yandan da içimde bir his var, ne de olsa babam, ya bir daha göremezsem? Gitsem anneme, onca fedakârlığına ihanet etmiş olacağım; gitmesem belki bir ömür vicdan azabı çekeceğim. İki ateş arasında kaldım, kalbim parçalanıyor. Sizce ne yapmalıyım?', true, 'Aile', 'Aile', 134, 2, 'approved', now() - interval '1692 minutes'),
  ('11567354-fb21-4685-bc4f-625829031a03', (select id from public.profiles order by random() limit 1), 'Kız kardeşim ağır bir hastalığa yakalandı ve tedavisi için yıllarca biriktirdiğim, kendi düğünüm için ayırdığım tüm parayı hiç düşünmeden verdim. Onun hayatı her şeyden önemliydi. Ama şimdi kendi düğünüm için param yok, sade bir nikâhla yetineceğiz ve nişanlımın ailesi bu yüzden bana yukarıdan bakıyor, kızlarına layık görmedikleri belli. Yaptığımdan pişman değilim, kardeşim iyileşiyor ve bu paha biçilemez. Ama bazen yorgun düştüğümde, herkes düğününü konuşurken içime bir burukluk çöküyor ve sonra bu bencilce düşünce için kendimden utanıyorum. Doğru olanı yaptım ama bedeli ağır. Bu burukluğu hissetmek beni kötü bir insan mı yapar?', true, 'Dram', 'Dram', 4500, 129, 'approved', now() - interval '18690 minutes'),
  ('eb4185f6-3a3e-4f10-8c9a-490200cf8643', (select id from public.profiles order by random() limit 1), 'Çok yakın bir arkadaşım vardı, kardeşim gibiydi, her sırrımı paylaşırdık. Bir gün küçük bir tartışmada, sırf haklı çıkmak için, onun bana güvenerek anlattığı en özel sırrını başkalarının yanında ağzımdan kaçırdım, hem de incitmek için. O an haklı çıktım ama onun yüzündeki o ihanete uğramış ifadeyi hiç unutamıyorum. O günden sonra benimle bir daha hiç konuşmadı, numaramı sildi, sosyal medyadan engelledi. Defalarca özür mesajı yazdım, hiç okumadı. Yıllar oldu, hâlâ onu çok özlüyorum, en güzel anılarım onunla. Bir anlık öfke, bir ömürlük dostluğu nasıl da bitiriverdi. Keşke o gün dilimi tutsaymışım. Bu pişmanlık en çok geceleri ağırlaşıyor.', true, 'Pişmanlık', 'Pişmanlık', 3096, 336, 'approved', now() - interval '1249 minutes'),
  ('22e590b8-89a1-481a-9a2f-c4fa1ebb2b18', (select id from public.profiles order by random() limit 1), 'Şirkette yıllardır en çok bana güvenilir, gizli müşteri bilgileri, finansal raporlar hep bende. Geçen ay rakip bir firma gizlice benimle iletişime geçti ve hayatımı değiştirecek kadar yüksek bir maaş teklif etti; tek şartları, bizim müşteri listemizi ve bazı gizli bilgileri onlara getirmemdi. Borçlarımı, çocuğumun eğitimini düşününce gözüm karardı, neredeyse evet diyecektim, sözleşme önümde duruyordu. Son anda vazgeçtim, çünkü o parayla yaşarken aynaya bakamayacağımı anladım. Ama itiraf etmeliyim ki o teklif hâlâ aklımda, o rakamı düşünüp duruyorum. Doğru olanı yaptım ama içimdeki o açgözlülüğü, o an verdiğim o kararsızlığı fark edince kendimden korktum.', true, 'İş Hayatı', 'İş Hayatı', 345, 52, 'approved', now() - interval '21149 minutes'),
  ('9c74b0b5-c569-411c-83e9-df67e1efe8ef', (select id from public.profiles order by random() limit 1), 'Sürekli takip edildiğimi hissediyorum; markete gitsem, işe gitsem aynı arabayı görür gibi oluyorum, telefonuma bilinmeyen numaralardan çağrılar geliyor, kapatıyorlar. Bir ara birinin evimin önünde beklediğini fark ettim ama gidip baktığımda kimse yoktu. Eşim ve ailem bana vehim yapıyorsun, stresten böyle hissediyorsun diyor. Belki haklılar, belki de değiller. Polise gitsem elimde somut bir kanıt yok, beni ciddiye almazlar, beni dengesiz sanırlar. Ama içimdeki bu tedirginlik, bu sürekli arkama bakma hâli giderek artıyor, geceleri uyuyamıyorum, perdeleri açamıyorum. Gerçekten biri mi peşimde, yoksa aklımı mı kaçırıyorum? Çok korkuyorum, ne yapacağımı bilmiyorum.', true, 'Korku', 'Korku', 1483, 781, 'approved', now() - interval '19845 minutes'),
  ('bd746720-9240-4e17-92bb-18da2aa6b16f', (select id from public.profiles order by random() limit 1), 'Kız kardeşimle çocukluğumuzdan beri çok yakınız, her sırrımızı paylaşırız. Geçen hafta onun telefonunu şarjda bırakırken yanlışlıkla ekranı gördüm ve dünyam başıma yıkıldı; benim nişanlımla aylardır gizlice, hem de sıradan değil çok yakın mesajlaşıyorlarmış. İkisi de bana en yakın, en güvendiğim iki insan. Anneme söylesem ailemiz paramparça olur, bayramlarda yüz yüze bakamayız; söylemesem bu ihanetle nasıl yaşarım, o sofraya nasıl otururum? Hiçbir şey bilmiyormuş gibi davranıyorum ama içim kan ağlıyor, her bakışta o mesajları görüyorum. Şu an kime güveneceğimi, kime sığınacağımı bilmiyorum, en güvendiğim iki insan da tükendi. Ne yapmalıyım, aklım almıyor.', true, 'Aile', 'Aile', 1116, 64, 'approved', now() - interval '4332 minutes'),
  ('cea74bc6-424c-44d5-89dc-d6c326244dca', (select id from public.profiles order by random() limit 1), 'Üniversitede burs için başvuran, benden çok daha zor şartlarda olan bir arkadaşım vardı. O bursu gerçekten hak ediyordu ama ben de istiyordum ve ben, ailemin tanıdıklarını araya sokarak o bursu kaptım, o ise alamadığı için okulu yarıda bıraktı, memleketine döndü. Yıllar sonra duydum ki hayalindeki mesleği yapamamış, zor bir hayatı olmuş. Bense o diplomayla rahat bir hayat kurdum. O bursun aslında onun olduğunu, onun hayatını çaldığımı hep biliyordum ama hiç yüzleşmedim. Şimdi bu rahat hayatın her gününde içimde bir sızı var, sanki başkasının üzerine basarak yükseldim. Keşke o gün biraz daha vicdanlı olsaymışım. Bu yükü nasıl taşıyacağım?', true, 'Pişmanlık', 'Pişmanlık', 2592, 168, 'approved', now() - interval '34755 minutes'),
  ('a809e348-3144-40a4-8948-480b32d1f0fe', (select id from public.profiles order by random() limit 1), 'Eşim çok iyi bir baba, çok iyi bir eş; sorumlu, çalışkan, güvenilir. Ama aramızdaki o ilk günkü kıvılcım, o heyecan yıllar içinde sönüp gitti, artık bir oda arkadaşı gibiyiz. Geçen ay eski bir arkadaşımla uzun yıllardan sonra karşılaştık ve o bana öyle bir baktı, öyle ilgilendi ki yıllardır hissetmediğim o heyecanı, o canlılığı yeniden duydum, yüzüm kızardı. Hiçbir şey yapmadım, yapmayacağım da; ailemi, çocuğumu asla riske atmam. Ama o akşam eve dönerken, sırf birinin bana o gözle bakması bile bana kendimi hatırlattı. İnsan sevdiği yuvada bu kadar görünmez hissedebilir mi? Eşime kızgın değilim, sadece çok yorgunum. Bu his geçer mi, yoksa bir uyarı mı?', true, 'Aşk', 'Aşk', 3936, 2001, 'approved', now() - interval '29592 minutes'),
  ('cf2c7b3e-9d1f-455e-90f2-d04f6d68ec67', (select id from public.profiles order by random() limit 1), 'Annem yıllardır yatalak, bakıma muhtaç ve bu yükün neredeyse tamamı benim üzerimde; iki kardeşim de işim var, çocuğum var diyerek aylarca uğramıyorlar bile. Ben hem çalışıyorum hem anneme bakıyorum, kendime ne bir gün ne bir nefes kalıyor, tükendim. Geçen gün bir an çok yoruldum ve içimden keşke bu çile bir an önce bitse diye geçirdim, sonra annemin yüzüne bakıp o düşünce için kendimden tiksindim, saatlerce ağladım. Onu çok seviyorum ama bu yorgunluk, bu yalnızlık bana en çirkin düşünceleri yaşatıyor. Kardeşlerime kırgınım, anneme bağlıyım, kendime acıyorum. Bu yükü tek başıma daha ne kadar taşırım, bilmiyorum. Yorulmak ihanet mi?', true, 'Dram', 'Dram', 839, 179, 'approved', now() - interval '14856 minutes'),
  ('8ee11610-624e-4a84-9f66-f90b07f082be', (select id from public.profiles order by random() limit 1), 'Çocuğumun doğum gününe, ailecek gittiğimiz lüks bir restoranda hesap geldiğinde kartım çekmedi, hesapta yetersiz bakiye çıktı, herkesin önünde rezil oldum. O an utancımdan yerin dibine girdim, hızlıca bir bahane uydurup başka kart aradım. Aslında o ay çok zordayım, işler bozuk ama kimseye belli etmiyorum, sosyal medyada hâlâ o güzel pozları paylaşıyorum, mutlu ve varlıklı görünüyorum. Bu sahte hayatı sürdürmek için borca giriyorum, gösteriş için battıkça batıyorum. Çocuğuma gerçeği, biraz idareli olmamız gerektiğini söyleyemiyorum çünkü onun gözünde küçük düşmekten korkuyorum. Bu gösteriş çukurundan nasıl çıkarım? Gerçeği kabul etmek neden bu kadar zor?', true, 'Utanç', 'Utanç', 150, 31, 'approved', now() - interval '23556 minutes'),
  ('36f5bd20-d65f-4ce3-985e-ddca891a0262', (select id from public.profiles order by random() limit 1), 'Yıllar önce, çok genç ve toydum, evli bir adamla ilişki yaşadım. Beni boşanacağına, bir hayat kuracağımıza inandırmıştı, ben de saf saf inandım, yıllarımı verdim. Sonunda boşanmadı, beni bir gün gözünü kırpmadan bıraktı, ben paramparça oldum. Aradan yıllar geçti, ben başka biriyle evlendim, güzel bir yuvam var. Ama geçen gün sosyal medyada onun, eşini hâlâ aldattığını, başka genç kızları aynı yalanlarla kandırdığını gördüm. İçimden o kızları uyarmak, o adamı ifşa etmek geliyor ama o zaman benim geçmişim de ortaya çıkar, yuvam sarsılır. Susarsam başka hayatlar yanacak, konuşursam kendiminkini yakacağım. Bu sırrı taşımak mı, yoksa bedelini göze alıp doğruyu söylemek mi? Vicdanım rahat değil.', true, 'Aldatma', 'Aldatma', 99, 9, 'approved', now() - interval '11086 minutes'),
  ('34a5b918-1944-4905-9d88-1351f97c9ec8', (select id from public.profiles order by random() limit 1), 'Eşim ve kayınvalidem benim asla çocuk istemediğimi, kariyerimi tercih ettiğimi düşünüyor ve bu yüzden bana sürekli bencil diyorlar, aile toplantılarında imalar yapıyorlar. Oysa gerçek şu ki ben yıllardır anne olamıyorum, sağlık sorunlarım var ve bunu kimseye, eşime bile söyleyemedim çünkü onun beni bırakmasından, kayınvalidemin beni eksik görmesinden korkuyorum. Her ay gizlice umutlanıp gizlice yıkılıyorum, tek başıma. Bencil damgasını yiyerek, içimde bu acıyı saklayarak yaşıyorum, gülümseyerek dayanıyorum ama içten içe bitiyorum. Eşime gerçeği söylesem belki destek olur, belki de gider. Bu yükü tek başıma taşımaya devam mı etmeliyim, yoksa korkularımı yenip konuşmalı mıyım? Çok yorgunum.', true, 'Aile', 'Aile', 2338, 234, 'approved', now() - interval '35320 minutes'),
  ('805bc0e8-620b-4eff-82aa-01c0634e1601', (select id from public.profiles order by random() limit 1), 'Kaza geçirdim, küçük bir kazaydı, kimse ciddi yaralanmadı ama o an panikledim ve durmadan, olay yerinden kaçtım. Kimsenin beni görmediğini düşünüyordum. Aradan haftalar geçti ve şimdi her kapı çalışında, her resmi zarf geldiğinde kalbim ağzıma geliyor, ya kameralara yakalandıysam, ya birileri plakamı not aldıysa korkusuyla yaşıyorum. Karşı taraf ciddi zarar görmedi ama benim kaçmam suç, bunu biliyorum. Gidip itiraf etsem cezası, sigortası derken başım büyük belaya girer; etmesem bu korkuyla, her an yakalanma endişesiyle ömür boyu yaşayacağım. O an neden durmadım, neden o paniğe yenildim, kendimi affedemiyorum. Bu vicdan azabı ve korku beni yiyip bitiriyor.', true, 'Korku', 'Korku', 44, 56, 'approved', now() - interval '19319 minutes'),
  ('cd4c1931-c7ac-4f23-a13b-d1ad55b57161', (select id from public.profiles order by random() limit 1), 'Eşimi gerçekten seviyorum ama itiraf etmeliyim ki onunla, ailelerimiz çok ısrar ettiği için, biraz da yaş ilerlediği için evlendim, büyük bir aşkla değil. İlk yıllar bunu hep eksiklik gibi hissettim, içimde hep bir keşke vardı. Ama o, ben hastayken, işsiz kaldığımda, en dipte olduğumda hiç bırakmadı, hep yanımda durdu, sırtını dönmedi. Yıllar içinde fark ettim ki ona duyduğum şey, o ilk günkü çarpıntıdan çok daha derin, çok daha sağlam bir bağmış. Belki onunla yıldırım aşkıyla başlamadık ama yavaş yavaş, gün gün gerçek bir sevgi büyüdü aramızda. İtirafım: büyük aşkı aramaktan vazgeçtiğimde, gerçek aşkın çoktan yanı başımda olduğunu anladım.', true, 'Aşk', 'Aşk', 120, 37, 'approved', now() - interval '27637 minutes'),
  ('e8cb2f28-6946-4654-8860-0a9f509a78e6', (select id from public.profiles order by random() limit 1), 'Çocukluğumda çok fakir büyüdüm, sınıfta herkesin markalı kalemleri, güzel beslenme çantaları varken benimkiler hep eski, yamalıydı ve bu yüzden çok utanır, kendimi hep eksik hissederdim. O günlerde içime kapanık, sessiz bir çocuktum. Yıllar sonra çok çalıştım, okudum, bugün hayalini bile kuramayacağım bir hayatım var. Geçen gün eski mahalleme gittim ve benim gibi yokluk çeken, gözlerinde o eski hüznü taşıyan çocuklar gördüm. O gün sessizce, kimse bilmeden, o okuldaki tüm ihtiyaç sahibi çocukların kırtasiye ve kıyafet masrafını üstlendim. Hiçbir teşekkür, hiçbir tanınma istemedim. İtirafım: o çocukların gözündeki o utancı silebilmek, küçük ben''e verebildiğim en güzel hediye oldu.', true, 'Diğer', 'Diğer', 527, 238, 'approved', now() - interval '13756 minutes'),
  ('389f5cfd-dfdf-4426-9322-3cdad2e3fbbb', (select id from public.profiles order by random() limit 1), 'Babaannem son yıllarında bizimle yaşadı ve ben gençtim, onun o sürekli tekrarlanan hikâyelerinden, eski anılarından sıkılır, bahane bulup odama kaçardım, onu dinlemeye sabrım yoktu. O hep gel biraz otur yanımda, sana anlatacaklarım var derdi, ben hep sonra derdim. Sonra o sonra hiç gelmedi, bir sabah uyanmadı. Şimdi o anlatmak istediği, kim bilir hangi değerli anıları, hangi öğütleri sonsuza dek kaybettim. Keşke o koltuğun yanına oturup saatlerce dinleseymişim, elini tutsaymışım. Yaşlıların o tekrarladığı hikâyeler aslında bize bırakmak istedikleri miraslarmış, ben geç anladım. Sevdiklerinizi, vakitleri varken dinleyin; çünkü o sonra çoğu zaman hiç gelmiyor.', true, 'Pişmanlık', 'Pişmanlık', 422, 37, 'approved', now() - interval '5288 minutes'),
  ('981027fc-3daf-4803-bfaa-6bcdbd4e8233', (select id from public.profiles order by random() limit 1), 'Eşimle aramız soğuyalı yıllar oldu, aynı evde ama ayrı dünyalarda yaşıyoruz, konuşmuyoruz bile. Bir süre önce iş yerinden biriyle, sadece sohbetle başlayan bir yakınlık kurdum; o beni dinliyor, gülümsetiyor, kendimi yıllar sonra biri tarafından görülmüş hissettiriyordu. Fiziksel hiçbir şey yaşanmadı ama duygusal olarak ona bağlandım ve bu beni dehşete düşürdü. Çünkü ben aldatan biri olmak istemiyorum, böyle yetişmedim. Şimdi hem eşime karşı suçluluk duyuyorum hem de bu yeni bağı koparmak istemiyorum çünkü beni yeniden hayata bağladı. Önce evliliğimi mi kurtarmaya çalışmalıyım, yoksa çoktan bittiğini kabul edip dürüstçe bir karar mı vermeliyim? Bu ikilemde boğuluyorum.', true, 'Aldatma', 'Aldatma', 9206, 547, 'approved', now() - interval '11113 minutes'),
  ('e6d97016-7a4b-44c7-ad84-23f41ee7968e', (select id from public.profiles order by random() limit 1), 'Kardeşim küçükken çok hastalıklıydı ve tüm ailenin ilgisi, sevgisi, kaynakları hep ona aktı; ben hep güçlü ol, sen iyisin nasılsa denip bir kenara itildim, kimse benim ne hissettiğimi sormadı. Yıllarca görünmez bir çocuk olarak büyüdüm, derdimi hep içime attım. Şimdi yetişkinim ve ailem benden, başarılı olduğum için hâlâ her şeyi bekliyor, her sorunda bana koşuyorlar ama kimse hâlâ nasılsın diye sormuyor. Geçen gün ailesel bir konuda ilk kez hayır dedim, artık benim de bir sınırım var dedim ve hepsi şoke oldu, beni bencillikle suçladılar. Bir ömür herkese verdikten sonra kendime sahip çıkmak bencillik mi? İçim buruk ama pişman değilim. Haklı mıyım?', true, 'Aile', 'Aile', 2529, 164, 'approved', now() - interval '4710 minutes'),
  ('9f39fcb4-2a69-4ba7-8af9-39219c73d6d2', (select id from public.profiles order by random() limit 1), 'Eşimin son zamanlarda davranışları çok değişti; geç saatlere kadar telefonla fısıldaşıyor, ben girince konuyu değiştiriyor, banka hesaplarını benden gizlemeye başladı, sürekli bir yerlere gidip geliyor. İçimde kötü bir his var, ya başı belada, ya tehlikeli işlere bulaştı diye geceleri uyuyamıyorum. Sorsam inkâr ediyor, üstüne bir de beni suçluyor, neden bana güvenmiyorsun diyor. Belki sadece iş stresidir, belki de hiç tahmin edemeyeceğim bir şeydir. Bu belirsizlik, bu bilememe hâli aldatılmaktan bile beter, içimi kemiriyor. Onun telefonunu karıştırmak mı, yoksa açıkça yüzleşip cevabını beklemek mi? Korkuyorum çünkü ne öğreneceğimi bilmiyorum. Bu sessiz korkuyla nasıl baş edeceğim?', true, 'Korku', 'Korku', 429, 108, 'approved', now() - interval '9636 minutes'),
  ('28dea9b7-efc6-45e4-9a8e-339cf0745bb0', (select id from public.profiles order by random() limit 1), 'Kocamla görücü usulü evlendik, başta birbirimize hitap etmekte bile zorlanıyorduk, koca bir yabancıydık. İlk gece ikimiz de odanın iki ucunda, utanarak oturduk, ne diyeceğimizi bilemedik. Aradan yıllar geçti ve şimdi onsuz bir günü bile düşünemiyorum; sabah kahvesini nasıl içtiğini, hangi şarkıya mırıldandığını, hangi haberde sinirlendiğini ezbere biliyorum. Geçen gün market dönüşü elinde tuttuğu çiçeği görünce, hiçbir özel gün olmadığı hâlde getirdiği o solgun çiçeği görünce gözlerim doldu. Demek ki sevgi bazen tanıdığın anda değil, birlikte yaşlandıkça, birlikte yıprandıkça büyüyormuş. İtirafım: hiç ummadığım bu evlilikte, sessiz ama derin bir aşkı buldum ve çok şükür ediyorum.', true, 'Aşk', 'Aşk', 311, 75, 'approved', now() - interval '29553 minutes'),
  ('3ea352cf-56a3-4f9c-ba7b-721c64162ed1', (select id from public.profiles order by random() limit 1), 'Eşim depresyona girdi ve aylardır yataktan çıkmıyor, çalışmıyor, konuşmuyor, bazen günlerce yüzünü göremiyorum. Ben hem evi geçindiriyorum hem çocuklara bakıyorum hem de onu ayakta tutmaya çalışıyorum, kendi yorgunluğumu kimseye anlatamıyorum çünkü herkes ona güçlü ol diyor, kimse bana sen nasılsın diye sormuyor. Bazı geceler tükeniyorum, kaçıp gitmek, her şeyi bırakmak istiyorum, sonra o çaresiz hâlini görünce vazgeçiyorum. Onu seviyorum ama bu yük çok ağır, içten içe ben de tükeniyorum, gülümsemem zorla. Ona destek olmaya devam mı etmeliyim, yoksa önce kendimi mi kurtarmalıyım? Sevdiğin insan boğulurken, seni de aşağı çekiyorsa ne yapmak gerek? Çok yalnızım.', true, 'Dram', 'Dram', 2700, 105, 'approved', now() - interval '31614 minutes'),
  ('744ca722-1928-47f5-85b9-39f885617f9e', (select id from public.profiles order by random() limit 1), 'Yıllar önce, gençken, en yakın arkadaşım bana çok ağır bir sırrını, başkalarının öğrenmesi onu mahvedecek bir şeyini emanet etmişti. Bir gün bir tartışmada, sırf onu kırmak, ona acı çektirmek için o sırrı başkalarına anlattım. O sır yüzünden arkadaşım okulu bıraktı, şehirden taşındı, hayatı altüst oldu. Yıllar sonra duydum ki o günden sonra kimseye güvenememiş, hep yalnız yaşamış. Bense bir anlık öfkemle bir insanın hayatını kararttım. Defalarca onu bulup özür dilemeyi düşündüm ama yüzleşmeye cesaret edemedim. Bu suçluluk yıllardır içimde, en mutlu anımda bile bir gölge gibi. Bir anlık öfke nasıl da bir ömrü yakabiliyormuş. Keşke o gün sussaymışım.', true, 'Pişmanlık', 'Pişmanlık', 661, 173, 'approved', now() - interval '38423 minutes'),
  ('80967077-875b-4801-b595-79c6e53ece84', (select id from public.profiles order by random() limit 1), 'Küçük bir işletmem var ve yıllardır yanımda çalışan, bana evladım gibi olan bir ustam vardı; dürüst, çalışkan, güvenilir. Geçen yıl işler çok bozuldu, batma noktasına geldim ve maaşları ödeyemez oldum. O, hiç sesini çıkarmadan, aylarca maaşsız çalıştı, hatta kendi birikiminden işe katkı yaptı, beni yalnız bırakmadı. İşler düzeldiğinde ise, utancımdan ve maddi sıkışıklıktan, ona hak ettiği o vefayı, o ödülü tam veremedim, başka bahaneler buldum, az verdim. Şimdi o emekli oldu ve ben her gün onun o sadakatini, ben kötü günümde yanımdaydım derken onun gözündeki o hayal kırıklığını hatırlıyorum. Vefasızlık ettim, bunu biliyorum. Telafi etmek için çok mu geç?', true, 'İş Hayatı', 'İş Hayatı', 1058, 93, 'approved', now() - interval '11572 minutes'),
  ('a33f0323-ac55-48b6-8359-82190db39986', (select id from public.profiles order by random() limit 1), 'Eşim çok agresif biri, öfkelendiğinde önce bağırıyor, sonra eşyalara zarar veriyor, duvarı yumrukluyor, kapıları kırıyor. Bana henüz el kaldırmadı ama o anlarda gözlerindeki o öfkeden, o kontrolsüzlükten dehşete düşüyorum, çocuğumla bir köşeye sinip bekliyoruz. Sakinleşince özür diliyor, ağlıyor, bir daha olmayacak diyor, ben de inanmak istiyorum çünkü gidecek yerim yok, ailem beni geri almaz, maddi olarak ona bağımlıyım. Herkese mutlu bir aileymişiz gibi davranıyorum. Ama içten içe biliyorum ki bu öfke bir gün benim ya da çocuğumun üstüne dönecek. Kaçmalı mıyım, ama nasıl, nereye? Bu korkuyla yaşamak çok yorucu. Aynı şeyi yaşayıp kurtulan var mı, ne yaptınız?', true, 'Korku', 'Korku', 685, 395, 'approved', now() - interval '27918 minutes'),
  ('f83d47c4-cd44-4763-9019-27acac6921ed', (select id from public.profiles order by random() limit 1), 'Eşim hamileliğim boyunca bana çok ilgisiz davrandı, yalnız bıraktı; en zor günlerimde yanımda olmadı. O dönem çok kırıldım, çok yalnızdım ve eski bir tanıdığımla sadece konuşarak, dertleşerek başlayan bir yakınlık, duygusal bir bağa dönüştü. Fiziksel hiçbir şey yaşanmadı ama kalbim bir süre başka yerdeydi ve bu beni çok utandırıyor. Şimdi bebeğim doğdu, eşim toparlandı, harika bir baba oldu, beni el üstünde tutuyor ve ben her gün o dönemki zayıflığımdan dolayı suçluluk duyuyorum. Ona, sen bana ilgisizken ben başka birine bağlanmıştım demeli miyim, yoksa o duygusal kayma bittiğine göre susmalı mıyım? Bu sırrı taşımak çok ağır ama açmak da yuvamı yıkabilir.', true, 'Aldatma', 'Aldatma', 1115, 236, 'approved', now() - interval '11502 minutes'),
  ('ec39e8d7-7b6b-422e-a050-4cfb731fe56d', (select id from public.profiles order by random() limit 1), 'Anne babam yıllar önce çok kötü ayrıldı ve ben ortada kaldım; ikisi de beni diğerine karşı bir silah gibi kullandı, birbirlerinin kötülüklerini bana anlattılar, beni taraf olmaya zorladılar. Çocukluğum bu savaşın ortasında geçti, ikisini de severken ikisinden de nefret etmeyi öğrendim. Şimdi ben yetişkinim, kendi ailem var ve ikisi de yaşlandı, ikisi de benden ilgi, bakım, vakit bekliyor, ama hâlâ birbirlerini çekiştiriyorlar, beni hâlâ aralarında bölüştürmeye çalışıyorlar. İkisine de kırgınım ama ikisi de annem babam. Bu yükü, bu ortada kalmışlığı bir ömür daha taşımak istemiyorum ama onları da bırakamıyorum. Bu kırgınlıkla onlara bakmaya devam mı etmeliyim? Çok yorgunum.', true, 'Aile', 'Aile', 30, 39, 'approved', now() - interval '31645 minutes'),
  ('0e32af0e-ae7d-4dc3-9515-7bfa69e98c6f', (select id from public.profiles order by random() limit 1), 'Üniversite yıllarımda, kantinde çalışan, benden yaşça büyük, sade giyimli bir ablayla herkesin önünde dalga geçtim, arkadaşlarımı güldürmek için onun hâline, konuşmasına laf attım. O hiçbir şey demedi, sadece başını önüne eğdi. Yıllar sonra çok zor bir işe başvurdum, hayatımın fırsatıydı ve karşımdaki üst düzey yönetici, o kantinde çalışan abla çıktı; meğer okurken çalışıyormuş, sonra çok başarılı olmuş. Beni tanıdı, gözlerindeki o tanımayı gördüm ama hiçbir şey belli etmedi, çok profesyonel davrandı, hatta işe aldı. O gün utancımdan yerin dibine girdim. Bana hak ettiğim dersi, kötülükle değil iyilikle verdi. O günden beri kimseyi, hiçbir şekilde küçümseyemiyorum.', true, 'Utanç', 'Utanç', 162, 43, 'approved', now() - interval '3095 minutes'),
  ('6ff24373-435a-4e09-9d00-f55e5e690c0b', (select id from public.profiles order by random() limit 1), 'Eşim trafik kazasında felç kaldı ve hayatımız bir anda altüst oldu; o yatağa bağlandı, ben hem ona bakıcı hem evin tek geçimi oldum, gece gündüz koşturuyorum. Onu seviyorum, asla bırakmam ama itiraf etmeliyim ki bazen, çok yorulduğum gecelerde, eski hayatımızı, birlikte yürüdüğümüz, güldüğümüz günleri hatırlayıp içten içe yıkılıyorum ve sonra bu düşünce için kendimden utanıyorum. O da çaresizliğinden bana yük oluyorum, beni bırak diye ağlıyor, ben asla diyorum ama içten içe ben de tükeniyorum, kimseye söyleyemiyorum. Bu fedakârlık bir ömür sürer mi, ben buna dayanabilir miyim? Sevdiğin insana bakmak kutsal ama bu kadar ağır olduğunda yorulmak ihanet mi? Çok yalnızım, çok yorgunum.', true, 'Dram', 'Dram', 1056, 185, 'approved', now() - interval '6098 minutes'),
  ('5b46a623-6b03-4a0c-ae5c-8a3238caf2ac', (select id from public.profiles order by random() limit 1), 'Annem yıllarca bana, bir gün başın derde girerse hangi şartta olursa olsun bana gel, ben hep yanındayım demişti. Ben de gençlik gururuyla, ben kendi ayaklarımın üstünde dururum, kimseye muhtaç değilim diye onu hep uzak tuttum, dertlerimi paylaşmadım. En zor günlerimde bile ona sığınmadım, güçlü görünmek istedim. Geçen yıl onu kaybettim ve şimdi her sıkıştığımda, ağlamak istediğimde sığınacak o kucağın artık olmadığını acıyla anlıyorum. Keşke o kapı açıkken, o kucak sımsıcakken biraz daha çocuğu olabilseymişim, biraz daha sığınsaymışım. Bağımsız olmaya çalışırken, hayatımın en güvenli limanını kullanmadan kaybettim. Bu pişmanlık, sığınacak yer kalmadığında çok daha acı veriyormuş.', true, 'Pişmanlık', 'Pişmanlık', 1076, 210, 'approved', now() - interval '5604 minutes'),
  ('34616b4d-f1fc-4f54-b952-20ef9cfe97a5', (select id from public.profiles order by random() limit 1), 'Çok genç evlendim, eşimi sevdiğimi sanıyordum ama aslında sadece o evden, ailemin baskısından kurtulmak için kaçar gibi evlendim. Yıllar geçtikçe onu sevmediğimi, bu evliliğin bir hata olduğunu anladım ama çocuklar oldu, düzen kuruldu, koparamadım. Şimdi orta yaştayım ve içimde hiç yaşamadığım bir hayatın özlemi, hiç hissetmediğim bir aşkın boşluğu var. Eşim iyi bir insan, bunu hak etmiyor ama ben de bu sevgisiz evlilikte yavaş yavaş soluyorum, içten içe ölüyorum. Onu üzmemek için bir ömür rol mü yapmalıyım, yoksa geç de olsa herkesin canını yakıp kendi gerçeğimin peşinden mi gitmeliyim? İyi bir insanı sevmemek de bir suç mu? Bu ikilemde yıllardır boğuluyorum.', true, 'Aldatma', 'Aldatma', 1082, 106, 'approved', now() - interval '32194 minutes'),
  ('2240a02f-5992-49f0-b5e8-e16c85c82cda', (select id from public.profiles order by random() limit 1), 'Komşumun küçük çocuğunun kollarında, bacaklarında garip morluklar görüyorum ve çocuk her gördüğümde gözlerini kaçırıyor, sinmiş gibi duruyor. İçimde çok kötü bir his var, ya o çocuğa evde kötü davranılıyorsa diye geceleri uyuyamıyorum. Ama emin değilim, belki düşüp çarpmıştır, belki yanlış anlıyorum ve boş yere bir aileyi suçlayıp insanların hayatını altüst ederim. Müdahale etsem, ihbar etsem ya yanılıyorsam; etmesem ya o çocuğa gerçekten bir şey oluyorsa ve ben sustuğum için... O minik gözlerdeki korkuyu görmezden gelemiyorum ama yanılma korkusu da beni felç ediyor. Ne yapmalıyım, kime danışmalıyım? Bir çocuğun hayatı söz konusuysa susmak mı, konuşmak mı doğru?', true, 'Korku', 'Korku', 921, 188, 'approved', now() - interval '31131 minutes'),
  ('5cc8de1d-5c27-4c49-b8e7-604810e9ad69', (select id from public.profiles order by random() limit 1), 'Yıllardır en yakın arkadaşımla kardeş gibiyiz, her şeyimizi paylaşırız, o benim sırdaşım. Ama bir süredir fark ettim ki ona arkadaşlıktan çok daha fazlasını hissediyorum, ona âşık olmuşum ve bu beni dehşete düşürüyor. Çünkü bunu söylersem ve o aynı şeyi hissetmiyorsa, hem onu kaybedeceğim hem de o eşsiz arkadaşlığı mahvedeceğim. Susarsam, onu başkasıyla görmenin acısına bir ömür katlanacağım, her gün biraz daha eriyeceğim. Her buluşmamızda bir şey söylemek için ağzımı açıp vazgeçiyorum, içimde koca bir yangın var. Riski göze alıp itiraf etmek mi, yoksa bu güzel dostluğu korumak için sevgimi gömmek mi? Kalbimi mi yoksa arkadaşlığımızı mı korumalıyım? Çok kararsızım.', true, 'Aşk', 'Aşk', 795, 18, 'approved', now() - interval '18104 minutes'),
  ('d7be4a5d-74cd-423c-b653-e430074a025c', (select id from public.profiles order by random() limit 1), 'Hayatım boyunca insanların beni sevmesi için sürekli bir şeyler yapmam gerektiğine inandım; başarılı olursam severler, fedakârlık yaparsam severler, herkesi memnun edersem değer görürüm diye düşündüm. Yıllarca kendimi geri plana atıp herkesi mutlu etmeye çalıştım, hayır demeyi bilmedim, sürekli verdim. Sonunda bir gün çöktüm, tükendim ve fark ettim ki bu kadar verirken kimse benim ne istediğimi, ne hissettiğimi sormamış bile. Çünkü insanlar beni değil, yaptıklarımı seviyormuş. Şimdi yavaş yavaş hayır demeyi, kendi sınırlarımı çizmeyi öğreniyorum ve bazıları uzaklaşıyor. İtirafım: kendim olduğumda yanımda kalanların gerçek olduğunu, gidenlerin ise zaten benim emeğimi sevdiğini geç de olsa anladım. Artık önce kendimi seçiyorum.', true, 'Diğer', 'Diğer', 585, 64, 'approved', now() - interval '16575 minutes'),
  ('a125a93b-0ada-4faa-a5d6-83a863a35002', (select id from public.profiles order by random() limit 1), 'Eşim çok dürüst, çok temiz kalpli bir insan; bana asla yalan söylemez, gözümün içine bakarak konuşur. Ama ben yıllar önce, evlenmeden hemen önce bir hata yaptım ve bunu ona hiç söylemedim, çünkü onun o saf güvenini, o berrak bakışını kaybetmekten ödüm kopuyor. Şimdi her dürüst sohbetimizde, her aramızdaki güzel anda, o saklı geçmiş bir hayalet gibi aramızda dolaşıyor ve içim sızlıyor. O bana her şeyini açarken, ben bir köşede koca bir sırrı saklıyorum ve bu beni iki yüzlü hissettiriyor. İtiraf etmek dürüstlük mü olur, yoksa sadece kendi vicdanımı rahatlatmak için onun huzurunu mu bozarım? Bazı sırlar sevdiğini korumak için mi saklanmalı, yoksa her gerçek söylenmeli mi? Yıllardır bu soruyla yaşıyorum.', true, 'Aldatma', 'Aldatma', 9441, 379, 'approved', now() - interval '27856 minutes'),
  ('9712020f-87a8-4d92-a0ad-083160e627b7', (select id from public.profiles order by random() limit 1), 'Oğlum büyüdü, evlendi ve gelinim geldiğinden beri yavaş yavaş onu benden uzaklaştırdı; eskiden her gün arayan oğlum artık haftada bir zar zor arıyor, bayramlarda bile bahane buluyor. Bunu kimseye söyleyemiyorum çünkü herkes kaynana gelin meselesi der, beni haksız çıkarır. Oysa ben sadece oğlumu özlüyorum, onu büyütmek için her şeyimi verdim ve şimdi bir yabancı gibi oldu. Gelinime kırgınım ama oğlumu kaybetmemek için ses çıkaramıyorum, gülümseyip her şeye katlanıyorum, içten içe ağlıyorum. Belki ben de fazla müdahale ediyorumdur, belki bırakmayı bilmiyorumdur. Bir evlat büyütüp sonra ona yabancı olmak ne acıymış. Geri çekilmek mi, yoksa hakkımı aramak mı? Çok yalnız hissediyorum.', true, 'Aile', 'Aile', 480, 264, 'approved', now() - interval '24215 minutes'),
  ('79d5d0a2-a42f-462c-9842-1e91ec55e956', (select id from public.profiles order by random() limit 1), 'Liseden mezun olurken, sınıfın en sessiz, en içine kapanık çocuğu vardı; kimse onunla konuşmaz, hatta onunla dalga geçerdi ve ben de o gruba uyup sustum, hiç sahip çıkmadım, bir kez bile yanına oturmadım. Yıllar sonra duyduk ki o çocuk o yalnızlığı kaldıramamış, kendine çok kötü şeyler yapmış. O haberi aldığım gün dünyam başıma yıkıldı; belki bir gülümseme, belki bir merhaba, belki bir kez yanına oturmak her şeyi değiştirebilirdi ama ben rahatımı bozmadım. O çocuğun o yalnız, mahzun yüzü yıllardır rüyalarıma giriyor. Keşke cesur olup o gruba karşı durup ona bir dost olabilseymişim. Bir iyiliğin ne kadar büyük olduğunu, yapmadığımda anladım. Bu pişmanlık ömürlük.', true, 'Pişmanlık', 'Pişmanlık', 1164, 147, 'approved', now() - interval '6676 minutes'),
  ('dcddc258-add9-479f-9fe4-7a149f285376', (select id from public.profiles order by random() limit 1), 'Eşim alkol bağımlısı ve yıllardır bu hastalıkla mücadele ediyoruz; ayık olduğunda dünyanın en iyi insanı, içtiğinde ise tanıyamadığım bir yabancı oluyor. Çocuklarım babalarının bu hâlini görmesin diye binbir oyun, binbir bahane uyduruyorum, herkesten saklıyorum, utanıyorum. Defalarca bırakacağım dedi, defalarca tekrar başladı ve her seferinde umudum biraz daha kırıldı. Onu seviyorum, hasta olduğunu biliyorum, terk etmek bana ihanet gibi geliyor ama çocuklarımı, kendimi de korumam gerek. Bu batağın içinde onunla birlikte boğulmak mı, yoksa çocuklarım için kurtarma simidine sarılıp gitmek mi? Sevgiyle acımayı, sadakatle kendini korumayı nasıl ayırt edeceğim? Çok yorgunum, bir yol göremiyorum.', true, 'Dram', 'Dram', 149, 25, 'approved', now() - interval '11114 minutes'),
  ('656b1d5c-44b6-4005-ae83-18f0a25d8c5b', (select id from public.profiles order by random() limit 1), 'Kocamla yıllardır evliyiz ve hayatımız bir rutine bindi; aynı sofra, aynı sözler, aynı sessizlikler. Bir ara gerçekten bu kadar mı, ömrümün sonuna kadar böyle mi diye düşünüp içimi bir boşluk kapladı, hatta başka hayatların hayalini kurdum. Sonra geçen kış ben grip olup günlerce yataktan kalkamadığımda, o işten erken çıkıp çorbamı yaptı, ilacımı verdi, alnıma ıslak bez koydu, ben uyuyana kadar saçımı okşadı. O an o sıradan saydığım rutinin aslında ne kadar değerli olduğunu, o sessizliğin aslında bir güven, bir huzur olduğunu anladım. İtirafım: heyecan arayan kalbim, gerçek sevginin gürültüsüz, gösterişsiz ama her zaman orada olan şey olduğunu fark etti. Şükrediyorum.', true, 'Aşk', 'Aşk', 2635, 929, 'approved', now() - interval '12076 minutes'),
  ('09577518-7a97-4b38-b55e-72ecf190deb4', (select id from public.profiles order by random() limit 1), 'Bir süredir telefonuma, sosyal medyama tanımadığım birinden mesajlar geliyor; benim her hareketimi, nereye gittiğimi, ne giydiğimi biliyor ve bunu mesajlarında ima ediyor, beni korkutuyor. Eşime söylemeye korkuyorum çünkü kıskanç biri, sen ne yaptın da bu adam sana takıldı diye beni suçlar. Polise gitsem elimde net bir delil yok, hesaplar sahte, beni ciddiye alırlar mı bilmiyorum. Artık dışarı çıkmaya, yalnız kalmaya korkuyorum, her an izlendiğimi hissediyorum, perdeleri kapatıyorum, kapıyı çift kilitliyorum. Bu korkuyla yaşamak bir kâbus. Kime güveneceğimi, nasıl korunacağımı bilmiyorum. Hiç bilmediğim, görmediğim birinin gözü üzerimde olması fikri uykularımı kaçırıyor. Ne yapmalıyım, lütfen yardım edin.', true, 'Korku', 'Korku', 679, 198, 'approved', now() - interval '40031 minutes'),
  ('cb433703-0b33-400b-9354-77dd67bdfd68', (select id from public.profiles order by random() limit 1), 'Babam çok otoriter bir adamdı, çocukluğumda hep korktum, asla onaylamadığını, gurur duymadığını hissettim, ne yapsam yetmezdi. Ben de onun onayını alabilmek için bir ömür çabaladım; istemediğim mesleği seçtim, onun beğeneceği biriyle evlendim, hep onun gözünde değerli olmak için yaşadım, kendi isteklerimi hep erteledim. Geçen ay vefat etti ve gariptir, içimde bir yas kadar bir özgürlük de hissettim ve bu beni çok korkuttu, kendimden utandım. Şimdi kırk yaşımda, hiç kendim için yaşamadığımı, hep birinin onayı için var olduğumu anlıyorum. Babamı seviyordum ama o onay hiç gelmedi ve ben kendimi onun gölgesinde kaybettim. Şimdi geç de olsa kendi hayatımı bulabilir miyim? Nereden başlamalıyım?', true, 'Aile', 'Aile', 2916, 1463, 'approved', now() - interval '10356 minutes'),
  ('21ee7210-cdf5-4eed-8b8b-33ae59353e32', (select id from public.profiles order by random() limit 1), 'Gençliğimde bana deli gibi âşık olan, beni gözü gibi seven bir insan vardı ama ben onun değerini bilmedim, hep daha iyisi gelir, ben daha çok şey hak ediyorum diye onu hafife aldım, kalbini kırdım, sonunda bıraktım. O yıllarca beni unutamadı, ben ise umursamadım bile. Şimdi yıllar geçti, ben birçok hayal kırıklığı yaşadım ve o kadar saf, o kadar gerçek bir sevginin bir daha asla karşıma çıkmadığını acıyla anladım. Geçen gün onu mutlu bir ailesiyle gördüm ve içim parçalandı; o sevgi benim olabilirdi ama ben kıymetini bilmedim. Kıymet bilmemek, en büyük cezayı insanın kendisine veriyormuş. Keşke o gün elimdeki o hazinenin değerini görebilseymişim. Bu pişmanlık hiç dinmiyor.', true, 'Pişmanlık', 'Pişmanlık', 2799, 211, 'approved', now() - interval '24579 minutes'),
  ('aeade032-f965-4e69-98ec-900bafc5cdd5', (select id from public.profiles order by random() limit 1), 'Bir meslektaşımın, çok değer verdiğim bir arkadaşımın işle ilgili büyük bir hata yaptığını, bunun şirkete ciddi zarar vereceğini fark ettim. Onu uyarmak, hatasını düzeltmesine yardım etmek yerine, terfi yarışında önüme geçmesin diye sustum, bilerek görmezden geldim. Hata büyüdü, patladı ve o işten kovuldu, kariyeri darmadağın oldu, ben ise onun yerine yükseldim. Şimdi o makamda otururken hiç mutlu değilim; her gün onun bana güvenen, sonra ihanete uğramış o yüzünü hatırlıyorum, başarımın üzerinde onun enkazı var. Bir arkadaşımı, birkaç basamak için feda ettim. Bu unvan bana hiçbir şey getirmedi, sadece içimde bir leke. Telafi etmenin, ona ulaşmanın bir yolu var mı, yoksa çok mu geç?', true, 'İş Hayatı', 'İş Hayatı', 93, 2, 'approved', now() - interval '32110 minutes'),
  ('8939771c-0e89-4495-afb4-f78fd44a8920', (select id from public.profiles order by random() limit 1), 'Eşimi yıllar önce, çok pişman olduğum bir dönemde bir kez aldattım ve o bunu hiç öğrenmedi. Aradan yıllar geçti, ben kendimi affettirmek için ona kusursuz bir eş oldum, her isteğini yerine getirdim, onu el üstünde tuttum. Ama geçen gün o, gözleri dolu dolu, bana sen dünyanın en sadık, en dürüst insanısın, sana güvenmek hayatımın en güzel şeyi dedi. O cümleyi duyunca içim paramparça oldu, çünkü o güvenin altında benim kocaman bir yalanım yatıyor. Onun o temiz güvenini hak etmiyorum ve bu beni içten içe yiyor. İtiraf etsem o güveni, o huzuru tamamen yıkarım; etmesem bu sahte kahramanlıkla yaşamaya devam ederim. Sevdiğini korumak için mi susmalı, yoksa dürüstlük için her şeyi yıkmalı mı? Yıllardır bu yükü taşıyorum.', true, 'Aldatma', 'Aldatma', 388, 100, 'approved', now() - interval '3840 minutes'),
  ('c9e45714-9928-4a8f-8335-9159c505fbb7', (select id from public.profiles order by random() limit 1), 'Ergenlik çağındaki kızımın son zamanlarda davranışları çok değişti; içine kapandı, geceleri ağladığını duyuyorum, yemek yemiyor, kollarını hep kapalı tutuyor ve benden bir şeyler saklıyor. İçimde annelik içgüdüsü kıyamet kopuyor, ya başına kötü bir şey geldiyse, ya birileri ona zarar veriyorsa diye geceleri uyuyamıyorum. Sorduğumda bir şeyim yok anne diyip odasına kaçıyor, ben de daha çok korkuyorum. Odasını gizlice aramak, telefonunu karıştırmak mı, yoksa onun güvenini zedelemeden konuşmasını beklemek mi? Çok bastırsam büsbütün uzaklaşacak, hiç dokunmasam belki yardıma muhtaçken yetişemeyeceğim. Bir annenin en büyük korkusu bu; çocuğunun acı çektiğini bilip ulaşamamak. Ne yapmalıyım, ona nasıl ulaşırım?', true, 'Korku', 'Korku', 1619, 204, 'approved', now() - interval '34481 minutes'),
  ('38cb2dd7-f6e1-4d15-98c1-eff0ee55c33e', (select id from public.profiles order by random() limit 1), 'Eşimle aramızda hiç tutku olmadı, görücü usulü, mantık evliliği yaptık ve ben yıllarca büyük aşkı yaşamadığım için kendimi eksik hissettim, romantik filmler izlerken içim burkuldu. Ama geçen gün kızımız çok hastalandı, hastanede günlerce nöbetleştik ve ben en korktuğum, en çaresiz anımda elimi tutan o ele, gözlerimin içine bakıp her şey düzelecek diyen o sese sığındım. O an anladım ki gerçek aşk, kalbin küt küt atması değil, en zor anda yanında o eli bulmakmış. Bizimki gümbürtüsüz, gösterişsiz ama sapasağlam bir bağmış ve ben yıllarca yanlış yere bakmışım. İtirafım: hayatın aşkı diye aradığım şey, yıllardır her sabah karşımda kahve içen o sessiz adamın ta kendisiymiş.', true, 'Aşk', 'Aşk', 172, 58, 'approved', now() - interval '5599 minutes'),
  ('1b3dc7ae-0a57-46ae-b02f-d144e9f2dd75', (select id from public.profiles order by random() limit 1), 'Babam yıllar önce bizi bırakıp gitti, annem beni büyütürken çok zorlandı ve ben de erken yaşta çalışmak, eve bakmak zorunda kaldım, çocukluğumu hiç yaşayamadım. Şimdi kendi çocuğum oldu ve ona her şeyin en iyisini vermeye, hiçbir şeyden mahrum bırakmamaya çalışıyorum. Ama itiraf etmeliyim ki bazen onun o kaygısız, mutlu çocukluğunu görünce, içimde hiç yaşayamadığım o günlere dair gizli bir kıskançlık, bir burukluk hissediyorum ve sonra bu histen dolayı kendimden tiksiniyorum, nasıl çocuğumu kıskanırım diye. Onu çok seviyorum, mutlu olması her şeyim ama içimdeki o yaralı çocuk hâlâ kendi payını istiyor. Bu burukluğu hissetmek beni kötü bir ebeveyn mi yapıyor? Bununla nasıl barışırım?', true, 'Dram', 'Dram', 215, 53, 'approved', now() - interval '30321 minutes'),
  ('f6773c07-587a-410f-b7e8-6a7a31590632', (select id from public.profiles order by random() limit 1), 'Bir arkadaşım vardı, çok iyi kalpliydi ama sade yaşardı, parası yoktu ve ben arkadaş ortamında, daha havalı görüneyim diye, onu yanımda gezdirmekten utanır, buluşmalara çağırmaz, ondan uzak dururdum. O bunu hissetti ama hiç yüzüme vurmadı, hep iyi davranmaya devam etti. Yıllar sonra ben çok zor bir döneme düştüm, herkes beni yüzüstü bıraktı, o havalı saydığım arkadaşlarım bir anda kayboldu. Tek arayan, tek yardıma koşan, o utandığım sade arkadaşım oldu. O gün utancımdan ağladım; ben onu görünüşü için harcamıştım, o ise beni en dipteyken kalbiyle kucakladı. Gerçek dostun parayla, gösterişle alakası yokmuş. O günden beri kimseyi dış görünüşüyle yargılamıyorum. Ona olan borcumu nasıl öderim?', true, 'Utanç', 'Utanç', 4534, 542, 'approved', now() - interval '14786 minutes'),
  ('59acfb3c-c37c-4c5b-9fe1-0361d72ac080', (select id from public.profiles order by random() limit 1), 'Eşim sürekli telefonuyla, bana ayıracak vakti yok; konuşurken bile gözü ekranda, sorduğum soruya zar zor cevap veriyor, yıllardır kendimi görünmez hissediyorum. Bu yalnızlıkta, bir uygulamada tanıştığım biriyle sadece dertleşerek başlayan bir yakınlık kurdum; o beni dinliyor, fikrimi soruyor, var olduğumu hissettiriyor. Fiziksel hiçbir şey yok ama her gün onu düşünüyorum ve bu beni hem mutlu ediyor hem dehşete düşürüyor, çünkü ben evliyim ve böyle biri olmak istemiyorum. Önce eşimle konuşup bu duvarı yıkmaya mı çalışmalıyım, yoksa çoktan bittiğini kabul edip dürüstçe ayrılmalı mıyım? Bir insan, sevdiği evinde bu kadar yalnız kalınca suçlu kim oluyor? Bu boşlukta boğuluyorum, bir akıl verin.', true, 'Aldatma', 'Aldatma', 151, 71, 'approved', now() - interval '25385 minutes'),
  ('077dcd5b-5812-474d-8ade-a9a3245492eb', (select id from public.profiles order by random() limit 1), 'Kardeşimle hep rekabet içinde büyütüldük; annem babam bizi sürekli kıyasladı, kim daha başarılı, kim daha iyi diye yarıştırdı ve bu yüzden hiçbir zaman gerçek kardeş olamadık, hep birbirimizi rakip gördük. Şimdi ikimiz de yetişkiniz ama o eski rekabet hâlâ sürüyor; onun başarısına için için üzülüyorum, başarısızlığına gizliden seviniyorum ve sonra bu hislerden dolayı kendimden iğreniyorum. Oysa keşke bir kardeşim olsa, derdimi paylaşacağım bir can olsa. Bu kini, bu rekabeti bana aşılayan ailem ama bedelini biz ödüyoruz, bir ömür birbirimizi sevemeden geçiriyoruz. Geç de olsa bu duvarı yıkıp ona sarılmak istiyorum ama nereden, nasıl başlayacağımı bilmiyorum. Kırılan bir kardeşlik onarılır mı?', true, 'Aile', 'Aile', 217, 23, 'approved', now() - interval '11533 minutes');
